        // ===== Seniors' Dream Guide: Garden Decryption =====
        add("pasterdream.seniors_dream.entry.garden_decryption_misty_dreaming_lotus", "Garden Decryption - Misty Dreaming Lotus");
        add("pasterdream.seniors_dream.entry.garden_decryption_misty_dreaming_lotus.page1", "You can find this strange relic in the Dyedream Plains. A beautiful flower named the \"Dreamforge Lotus\" grows on its top, and below the flower lie hints left by the earliest Dreamseeker. Perhaps you should search for the corresponding plants according to her hints...");
        add("pasterdream.seniors_dream.entry.garden_decryption_misty_dreaming_lotus.page2", "Perhaps you should seek the answer in the bells, clouds, glow, and parasols from Qinyumeng's hints?");
        add("pasterdream.seniors_dream.entry.garden_decryption_misty_dreaming_lotus.page3", "The flower obtained after solving the puzzle seems able to be used to travel to the wind's dream, and to seek the legendary divine fox...");
        add("pasterdream.seniors_dream.entry.garden_decryption_nippy_edelweiss", "Garden Decryption - Nippy Edelweiss");
        add("pasterdream.seniors_dream.entry.garden_decryption_nippy_edelweiss.page1", "In the snowy plains of the Dyedream World, you may come across this peculiar structure. On the desk below, you will find the notes left by the very first Dreamseeker. You need to find the corresponding plants and creatures according to her hints.");
        add("pasterdream.seniors_dream.entry.garden_decryption_nippy_edelweiss.page2", "It seems you should start with words like \"dreamdyed\", \"lantern\", and \"peculiar\". Go and take a look.");
        add("pasterdream.seniors_dream.entry.garden_decryption_nippy_edelweiss.page3", "The flower obtained after solving the puzzle seems to have a peculiar low-temperature touch...");
        add("pasterdream.seniors_dream.entry.garden_decryption_nine_tailed_fox", "Garden Decryption - Nine-Tailed Fox");
        add("pasterdream.seniors_dream.entry.garden_decryption_nine_tailed_fox.page1", "In the dream, you will sometimes see relics with statues shaped like foxes. Above, in the Dreamseeker's Eternal Scroll, lie the hints given by Qinyumeng. Perhaps a peculiar lotus is needed, or maybe you should first take a look at the other garden decryptions...");
        add("pasterdream.seniors_dream.entry.garden_decryption_nine_tailed_fox.page2", "Once you awaken the Nine-Tailed Fox, she will fulfill one of your wishes. As for how to fulfill the wish, that young lady has told you in the book as well...");
        add("pasterdream.seniors_dream.entry.garden_decryption_nine_tailed_fox.page3", "--That wondrous divine fox will fulfill your wish, or grant you a charm that wards off evil.");

        // ===== Seniors' Dream Guide: full translation =====
        add("item.pasterdream.charged_amethyst", "Charged Amethyst");
        add("item.pasterdream.dream_notes_book", "Dreamseeker Notes Book");
        add("item.pasterdream.molten_gold_ingot", "Molten Gold Ingot");
