        add("pasterdream.seniors_dream", "Seniors' Dream Guide");
        add("pasterdream.seniors_dream.catalyst.test", "Test");
        add("pasterdream.seniors_dream.catalyst.test.desc", "A test category.");
        add("pasterdream.seniors_dream.entry.welcome", "Welcome");
        add("pasterdream.seniors_dream.entry.welcome.page0", "If you can read this text, the tome is working properly!");
        add("pasterdream.seniors_dream.landing_text", "Welcome to PasterDream: Reborn, the remake of PasterDream. This book covers the new guidance and item info. Dreamseeker, may the star river enter your dreams and a breeze rest by your pillow.");
        add("pasterdream.seniors_dream.category.rules", "Mechanics");
        add("pasterdream.seniors_dream.category.rules.desc", "This chapter introduces the mechanics of the mod.");
        add("pasterdream.seniors_dream.category.rules_shadow_difficulty", "Shadow Difficulty System");
        add("pasterdream.seniors_dream.category.rules_shadow_difficulty.desc", "As you sink deeper into the mire of madness, the beings in the shadows begin to notice you. They are no illusion — when your mental defenses grow thin enough, Shadow Creatures will manifest in the darkness around you. The more fragile your sanity, the more often they appear, and the more horrifying their kinds.$(br2)--Shadow Invasion");
        add("pasterdream.seniors_dream.entry.meltdream", "Melt Dream Energy");
        add("pasterdream.seniors_dream.entry.meltdream.page0", "In the lower-left corner of the screen is an energy-bar-like icon: that is your Melt Dream Energy. For weapons with a Combat Art, right-clicking consumes Melt Dream Energy to trigger the corresponding Combat Art.");
        add("pasterdream.seniors_dream.entry.meltdream.page1", "A look at the Melt Dream Energy bar interface.");
        add("pasterdream.seniors_dream.entry.meltdream.page2", "Ways to gain Melt Dream Energy:$(br)Opening each Melt Dream Crystal Chest grants 2 Melt Dream Energy;$(br)Eating certain foods grants some Melt Dream Energy;$(br)Wearing certain curios also restores Melt Dream Energy, mainly the Melt Dream Aura Ring and the Worldtree Seedpod.");
        add("pasterdream.seniors_dream.entry.meltdream.page3", "A display of some items related to Melt Dream Energy.");
        add("pasterdream.seniors_dream.entry.san", "SAN");
        add("pasterdream.seniors_dream.entry.san.page0", "You may have already noticed a brain-like icon in the lower-right corner of your screen: that is your SAN value.");
        add("pasterdream.seniors_dream.entry.san.page1", "A look at the SAN value interface.");
        add("pasterdream.seniors_dream.entry.san.page2", "SAN value effects:$(br)SAN>=90%% Gain Cheer Up$(br)SAN<=60%% Gain Lethargy$(br)SAN<=40%% Gain Trance$(br)SAN<=20%% Gain Insanity I$(br)SAN<=10%% Gain Insanity II$(br)SAN<=1%% Gain Insanity III$(br2)For the detailed effects of each buff, please refer to the corresponding chapter.");
        add("pasterdream.seniors_dream.entry.san.page3", "SAN changes caused by the environment:$(br)SAN is affected by biome type and light level. The formula is:$(br)Total change rate = (SAN Aura / 1200) + biome influence + (light level - 7) * 0.0001");
        add("pasterdream.seniors_dream.entry.san.page4", "Biome influence mainly manifests as:$(br)Biomes in the Deep Dark and under the Lamp Shadow lower the player's SAN;$(br)Biomes in the Dyedream World raise the player's SAN;$(br)Other biomes cause no strong interference.$(br2)A SAN Aura of n means the player gains n SAN per minute, excluding other influences (biome influence and light level).");
        add("pasterdream.seniors_dream.entry.san.page5", "Other ways to lose SAN:$(br)Standing within the Insanity Aura of a Shadow Creature;$(br)Holding an item that carries an Insanity Aura;$(br)Certain item skills also consume SAN.$(br2)Ways to actively restore SAN:$(br)Use specific items or foods;$(br)Equip curios with a SAN Aura;$(br)Have the Cook and Rest buffs;$(br)Stay in a brightly lit environment.");
        add("pasterdream.seniors_dream.entry.san.page6", "A display of some items related to SAN.");
        add("pasterdream.seniors_dream.entry.evasion", "Blink");
        add("pasterdream.seniors_dream.entry.evasion.page0", "Released with the C key by default. Using Blink consumes 2 hunger points, performs a quick dash, and resets your fall distance. Blink grants a brief window of invulnerability. The default cooldown is 1 second; Creative mode has no cooldown.");
        add("pasterdream.seniors_dream.entry.evasion.page1", "Used on the ground, you dash toward the position your crosshair points at;$(br)Used while sneaking on the ground, you dash in the opposite direction of your crosshair;$(br)Used in water, the vertical offset of your crosshair has no effect.");
        add("pasterdream.seniors_dream.entry.fishing", "Fishing");
        add("pasterdream.seniors_dream.entry.fishing.page0", "In our leisure time, we may sit by the water with a fishing rod, accepting the ocean's bounty (or going home empty-handed). Now, fishing near the ocean may reel in a treasure from the depths — a Deep Sea Treasure. Even in the vast oceans of the dream, you can cast your bobber and obtain treasure. The higher your luck, the more likely you are to obtain a Deep Sea Treasure. Sometimes, you may even reel in one glowing with a strange light...");
        add("pasterdream.seniors_dream.entry.fishing.page1", "Perhaps the Deep Sea Treasures fished out in the dream can yield some unique loot, such as colorful crystal fragments, and a bucket of spring water shimmering with light...");
        add("pasterdream.seniors_dream.entry.shadow_difficulty", "Shadow Difficulty");
        add("pasterdream.seniors_dream.entry.shadow_difficulty.page0", "The Shadow Difficulty level is made up of both the player and the world. If an existing effect involves interaction with the player, the player difficulty takes priority; otherwise, the world difficulty applies.");
        add("pasterdream.seniors_dream.entry.shadow_difficulty.page1", "There are four main Shadow Difficulty levels:$(br)Very Easy: Shadow invasions almost never occur, and even when they do, they are extremely weak.$(br)Easy: Shadow invasions occur when SAN<20%%.$(br)Normal: Shadow invasions begin to appear when SAN<60%%, and monsters drop richer loot.$(br)Hard: Shadow invasions appear when SAN<82.5%%, and their health and attack are doubled, with loot doubled as well.");
        add("pasterdream.seniors_dream.entry.shadow_creature_behavior", "Shadow Creature Behavior");
        add("pasterdream.seniors_dream.entry.shadow_creature_behavior.page0", "When the Shadow Difficulty is at least \"Easy\", some Shadow Creatures gain special skills:$(br)Shadow Golems use shockwaves that deal higher damage.$(br)Shadow Hands steal the player's sanity with their attacks.$(br)Terrorbeaks roar, lowering the player's SAN (including the player's real-life sanity).$(br)Wailing Shadow Ghosts summon ordinary Shadow Ghosts.");
        add("pasterdream.seniors_dream.category.foretold_dream", "The Foretold Dream");
        add("pasterdream.seniors_dream.category.foretold_dream.desc", "This chapter introduces the new mechanics and knowledge added to the vanilla dimensions.");
        add("pasterdream.seniors_dream.category.foretold_dream_items", "New Items");
        add("pasterdream.seniors_dream.category.foretold_dream_items.desc", "New items added to the vanilla dimensions.");
        add("pasterdream.seniors_dream.category.foretold_dream_structures", "New Structures");
        add("pasterdream.seniors_dream.category.foretold_dream_structures.desc", "New structures added to the vanilla dimensions.");
        add("pasterdream.seniors_dream.entry.titanium", "Titanium");
        add("pasterdream.seniors_dream.entry.titanium.page0", "Deep underground in the Overworld, you may find an ore called Titanium. It requires a pickaxe made of a material stronger and harder than iron to mine. Like most ores, Fortune can yield more raw ore. Tools made of Titanium are a bit handier than diamond ones; perhaps you can channel the power of dreams into your titanium wares...");
        add("pasterdream.seniors_dream.entry.titanium.page1", "--Titanium possesses extremely strong corrosion resistance; even after long weathering it still gleams. Just like that dream not yet awakened — savoring it again after a long time feels like yesterday.");
        add("pasterdream.seniors_dream.entry.molten_gold", "Molten Gold");
        add("pasterdream.seniors_dream.entry.molten_gold.page0", "While exploring the depths of the Nether, you may find an ore resembling gold that gleams with a strange light. This peculiar ore only needs an iron pickaxe to mine and benefits from Fortune. When holding tools made of Molten Gold, you can right-click to consume your hunger and gain Swiftness. The swords and pickaxes crafted from it seem to have even stronger upgrades...");
        add("pasterdream.seniors_dream.entry.molten_gold.page1", "--A metal forged amid blazing fire and scorching heat. If you truly wish to grasp its power, perhaps you need the resolve to walk into a sea of flames.");
        add("pasterdream.seniors_dream.entry.soul_dust", "Soul Dust");
        add("pasterdream.seniors_dream.entry.soul_dust.page0", "In the Nether's Soul Sand Valley, strange soul soil mixed with some white substance sometimes appears. They are called Soul Ore Soil; mining them grants Soul Dust. These soils can be mined by hand, but using a tool is not only faster — a Fortune-enchanted tool yields even more Soul Dust. Soul Dust can be used to craft Soul Essence, which in turn is used to make necklace, ring, and belt blanks, and eventually various curios.");
        add("pasterdream.seniors_dream.entry.soul_dust.page1", "--May the restless souls of the Nether find release, and may the Dreamseeker walking through dreams grant the departed the peace of the living.");
        add("pasterdream.seniors_dream.entry.sculk_upgrade", "Sculk Upgrade");
        add("pasterdream.seniors_dream.entry.sculk_upgrade.page0", "The fallen dynasty can never see daylight again, yet the power it stored flows endlessly. Now that you have defeated the strongest guardian here, try infusing it into Netherite armor, and let the forbidden power of that ancient civilization serve you. The upgraded Sculk Echo set is not only sturdier — it also grants you the protection of the echo, so you no longer fear the sculk. Even in the face of deeper darkness, the echo's power lends you a bit of courage.");
        add("pasterdream.seniors_dream.entry.sculk_upgrade.page1", "--When wearing the Sculk Echo set, what I feel is not just power, but a deeper, more ancient darkness and dread coiling around my ears, never fading. Like a nightmare, it calls out for me to embrace it...");
        add("pasterdream.seniors_dream.entry.inferno_sword", "Inferno Sword");
        add("pasterdream.seniors_dream.entry.inferno_sword.page0", "Use Ancient Debris, Blaze Powder, and a block of Molten Gold to strengthen the Molten Gold Sword, upgrading it into the Inferno Sword. It is as sharp as a diamond sword, and it sears enemies with a long-lasting blaze. If an enemy is already burning, this sword prolongs their torment.");
        add("pasterdream.seniors_dream.entry.inferno_sword.page1", "Once strengthened, the sword earns the name \"Melt Corpse\". It becomes lighter, and the wielder can actively unleash a Combat Art, granting the sword the \"Bone-melting Slash\", making its next strike deadlier. If the enemy would suffer a long blaze, the Bone-melting Slash also quenches their flames, slowing their movements.$(br2)--Bathed in the fires of war, forged upon the anvil of battle.");
        add("pasterdream.seniors_dream.entry.kusanagi", "Kusanagi");
        add("pasterdream.seniors_dream.entry.kusanagi.page0", "This sword named \"Kusanagi\" is as sharp as one made of diamond, and it inflicts painful, lethal venom upon the creatures it wounds. When two hundred lives have fallen to this blade, it reveals its full might as a divine weapon — Kusanagi becomes even sharper, and its victims suffer a longer, crueler poison. The wielder can actively unleash a Combat Art, granting it \"Extreme Sharpness\", making the divine blade's next strike more deadly.");
        add("pasterdream.seniors_dream.entry.kusanagi.page1", "--This sword may be called the Sword of the Cloud Cluster, but this mod has no Yamata no Orochi; it cannot be used as a holy relic to summon heroic spirits, nor can its Noble Phantasm be unleashed upon foes as an eight-headed raging wave.");
        add("pasterdream.seniors_dream.entry.tide_sword", "Beihai Ruo Tide Sword");
        add("pasterdream.seniors_dream.entry.tide_sword.page0", "One day, you sense that the Blue Dew found in Deep Sea Treasures resonates with the Tide Sword you forged. So you further polish the Blue Dew and try to set it into the Tide Sword. Now this sword bears the name of the ancient sea god: it is sharper than ever, and its wielder can actively unleash \"Surging Current\" to dash swiftly through water. Moreover, if your enemy fights you in water, your next slash after releasing Surging Current will be even more deadly.");
        add("pasterdream.seniors_dream.entry.tide_sword.page1", "--Nine rivers surge into the sea-god's embrace; a lone peak looks down, aweing the sea spirits.");
        add("pasterdream.seniors_dream.entry.desert_sword", "Chenjingmen Desert Sword");
        add("pasterdream.seniors_dream.entry.desert_sword.page0", "The warrior buried in the desert has not found rest; now it is your turn to fulfill his will. Once his wish is granted, he will help you unleash the full power of the great desert sword. This ancient hero's blade regains its true name — \"Chenjingmen\" Desert Sword. It not only restores its former sharpness, but also grants its wielder the ability of \"Desperate Counterattack\".");
        add("pasterdream.seniors_dream.entry.desert_sword.page1", "After activating Desperate Counterattack, you briefly gain more health to endure attacks, and the more damage you take, the more deadly your ensuing counter-slice will be.$(br2)--Looking back, the demonic miasma yet lingers; tell me, in this world, where are the heroes?");
        add("pasterdream.seniors_dream.entry.deep_sea_treasure", "Deep Sea Treasure");
        add("pasterdream.seniors_dream.entry.deep_sea_treasure.page0", "While fishing in various dimensions, you may sometimes find these exquisite little chests. Opening them grants small treasures, and your luck affects the rarity of what you get. Moreover, some treasures seem to glow, and the loot inside appears extraordinary. Apart from common items, it is said there is a weapon from the deep sea, as well as some treasured keepsakes born from dreams.");
        add("pasterdream.seniors_dream.entry.deep_sea_treasure.page1", "Perhaps you could try fishing for some luck in the dream?$(br2)--Melt into the dream of the sea... wait, what do you mean you fished out an axolotl?");
        add("pasterdream.seniors_dream.entry.thermal_dagger", "Thermal Dagger");
        add("pasterdream.seniors_dream.entry.thermal_dagger.page0", "When you open a Deep Sea Treasure, you may obtain this peculiar little dagger. While held in your main hand, you swim faster. The dagger's speed and sharpness both slightly exceed those of an iron sword. Interestingly, attacking enemies with this weapon produces a sizzling, frying sound.");
        add("pasterdream.seniors_dream.entry.thermal_dagger.page1", "Long ago, a visitor from the sky crashed into the ocean, seeking a way home while lost. This peculiar dagger must have been crafted by that celestial visitor.$(br2)--Friendly reminder: this dagger cannot take on the Leviathan of death alone; upon leaving the ocean, please check yourself for the Cala virus.");
        add("pasterdream.seniors_dream.entry.fortune_jelly", "Fortune Jelly");
        add("pasterdream.seniors_dream.entry.fortune_jelly.page0", "While exploring this world, you should have found this green jelly in some chests. Eating this bouncy little treat makes Lady Luck smile upon you a little more.");
        add("pasterdream.seniors_dream.entry.fortune_jelly.page1", "Although we haven't figured out how this jelly is made, it seems the luck inside it can be extracted through brewing.");
        add("pasterdream.seniors_dream.entry.mortar", "Mortar");
        add("pasterdream.seniors_dream.entry.mortar.page0", "Ancient alchemists used mortars to assist in brewing potions, pursuing the Fifth Element that could turn stone into gold. Of course, if you have no need to study alchemy, you can use this tool to craft dyes that exist in dreams.$(br2)You can store liquid inside the mortar. Right-click on a liquid source to store it, and left-click to take it out. You need to place it on a crafting table to craft Dyedream Dye and other things made with the mortar. After crafting, the mortar can be recovered, but the liquid stored inside is consumed.");
        add("pasterdream.seniors_dream.entry.mortar.page1", "--People of the past used it to pursue the miracle of the One; now those who walk through dreams use it to distill the mysteries of the dream.");
        add("pasterdream.seniors_dream.entry.weapon_workshop", "Weapon Workshop");
        add("pasterdream.seniors_dream.entry.weapon_workshop.page0", "As your tools are upgraded, your crafting table gradually proves inadequate for tool-making. So you turn your gaze to the blacksmith's equipment in villages — yet you seem unable to replicate it...$(br2)Perhaps you need to loosen your purse strings and trade with the village toolsmith a few more times; once he becomes a master, he should be willing to sell you the blueprint for a Weapon Workshop.$(br2)Besides, with this workshop, it seems you can also make use of the Enhance Stones you've found.");
        add("pasterdream.seniors_dream.entry.weapon_workshop.page1", "--This equipment and technique existed as early as the Middle Ages. Ancient though they are, they suffice for me to forge more powerful tools.");
        add("pasterdream.seniors_dream.entry.dyedream_sky_island", "Dyedream Sky Island");
        add("pasterdream.seniors_dream.entry.dyedream_sky_island.page0", "Upon your first arrival, you will find this pink sky island in the Overworld. Its existence seems somewhat unreasonable, as if... a dream. Climb onto the island and you'll see a strange rift. Your first contact brings no direct reaction, but it gives you a strange dream. When you wake, you find a note has mysteriously appeared in your pocket. Perhaps after reading this mysterious note, you should touch that rift again...$(br2)--If this sky island is the reflection of dream power, then when I pass through the rift, am I truly in \"reality\" or \"a dream\"?");
        add("pasterdream.seniors_dream.entry.dyedream_sky_island.page1", "");
        add("pasterdream.seniors_dream.entry.the_lost_sword_tomb", "The Lost Sword Tomb");
        add("pasterdream.seniors_dream.entry.the_lost_sword_tomb.page0", "The Lost Sword Tomb is a structure found only in jungle biomes. In its center, a sword is embedded in stone — a Sword in the Stone that requires brute force and miracles to pull out, unless...$(br2)The Lost Sword obtained can be upgraded with the power of the jungle into Kusanagi. Yet this blade seems rather bloodthirsty; try to satisfy it, and perhaps it will reveal even greater power it has not yet shown...");
        add("pasterdream.seniors_dream.entry.the_lost_sword_tomb.page1", "");
        add("pasterdream.seniors_dream.entry.fisherman_hut", "Fisherman Hut");
        add("pasterdream.seniors_dream.entry.fisherman_hut.page0", "In the beach biomes of the Overworld, you may sometimes find these fisherman huts — homes of fishermen who left their villages to live by the sea. In the chest inside, you can find treasures the fisherman hauled out of the ocean.$(br2)Of course, sometimes there are Deep Sea Treasures inside as well. Perhaps the fisherman didn't know how to open them and merely kept them — what a case of keeping the casket and returning the pearl.");
        add("pasterdream.seniors_dream.entry.fisherman_hut.page1", "--I believe they must have their own reasons for living by the sea alone. Perhaps this deep ocean hides even deeper secrets.");
        add("pasterdream.seniors_dream.entry.desert_fortress", "Desert Fortress");
        add("pasterdream.seniors_dream.entry.desert_fortress.page0", "In the deserts of the Overworld, you may sometimes find this strange ruin, apparently already occupied by pillagers and husks. Perhaps you can deal with these foes while you're exploring...");
        add("pasterdream.seniors_dream.entry.desert_fortress.page1", "");
        add("pasterdream.seniors_dream.entry.desert_fortress.page2", "Legend says that a warrior with an unfulfilled will lies buried deep underground, awaiting a wayward traveler to come and fulfill his last wish and inherit his legacy...");
        add("pasterdream.seniors_dream.entry.desert_fortress.page3", "");
        add("pasterdream.seniors_dream.entry.twilight_lantern", "Twilight Lantern");
        add("pasterdream.seniors_dream.entry.twilight_lantern.page0", "After Calais journeyed to the Lamp Shadow World, she left using the power of the shadows. Though she broke her pact with the shadows, she sealed away her contingency for the dark dream at the very top of the Nether, suppressing it with a Dyedream Bed. But a cage can never fully contain the power of the shadows. Now the shadows have overflowed, and after learning enough secrets, you decide to venture into the eternal dark dream to find out the truth.");
        add("pasterdream.seniors_dream.entry.twilight_lantern.page1", "");
        add("pasterdream.seniors_dream.entry.twilight_lantern.page2", "Since your mind is made up, go light the cage with a Melt Dream Crystal Fragment. The cage will overflow with even more shadow power, and when you witness this revelry of shadow monsters, sleep upon the twilight bed to enter the dream that flows with darkness.");
        add("pasterdream.seniors_dream.entry.twilight_lantern.page3", "This will be an exceedingly perilous battle, so be sure to prepare yourself to witness the darkest of dreams.");
        add("pasterdream.seniors_dream.category.foretold_dream_buffs", "New Buff Effects");
        add("pasterdream.seniors_dream.category.foretold_dream_buffs.desc", "The buff effects added by the mod.");
        add("pasterdream.seniors_dream.entry.rest", "Rest");
        add("pasterdream.seniors_dream.entry.rest.page0", "Rest is a buff that gradually restores the player's SAN, granting +1.2 SAN Aura per level.$(br2)You can obtain this buff by lying on a vanilla bed, or by standing near a QYM Doll or a campfire.");
        add("pasterdream.seniors_dream.entry.cheer_up", "Cheer Up");
        add("pasterdream.seniors_dream.entry.cheer_up.page0", "A buff obtained when the player's SAN>=90%%. Its effects are:$(br)Blink cooldown -10%%;$(br)Movement speed +0.05;$(br)Attack speed +0.05;$(br)Skill cooldown -10%%.");
        add("pasterdream.seniors_dream.entry.lethargy", "Lethargy");
        add("pasterdream.seniors_dream.entry.lethargy.page0", "A buff obtained when the player's SAN<=60%%. Its effects are:$(br)Blink cooldown +50%%;$(br)Movement speed -10%%;$(br)Attack speed -0.1;$(br)Skill cooldown +20%%.");
        add("pasterdream.seniors_dream.entry.trance", "Trance");
        add("pasterdream.seniors_dream.entry.trance.page0", "A buff obtained when the player's SAN<=40%%. Its effects are:$(br)Blink cooldown +100%%;$(br)Movement speed -20%%;$(br)Attack speed -0.2, attack -1;$(br)Skill cooldown +50%%.");
        add("pasterdream.seniors_dream.entry.insane", "Insanity");
        add("pasterdream.seniors_dream.entry.insane.page0", "A buff obtained when the player's SAN<=20%%. Its effects are:$(br)Blink cooldown +200%%;$(br)Movement speed -30%%;$(br)Attack speed -0.4, attack -2;$(br)Attack and reach distance -0.2.");
        add("pasterdream.seniors_dream.entry.insane.page1", "While under this effect, your vision shakes uncontrollably; the higher the level of insanity, the more violent the shaking of your screen.");
        add("pasterdream.seniors_dream.entry.insane.page2", "When the Shadow Difficulty is at least \"Easy\", Insanity III causes the player to continuously lose health.");
        add("pasterdream.seniors_dream.entry.cook", "Cook");
        add("pasterdream.seniors_dream.entry.cook.page0", "This buff can be obtained by eating certain foods from this mod, as well as foods from the mods it integrates with. Each level grants +1.2 SAN Aura.");
        add("pasterdream.seniors_dream.entry.chaos", "Confusion");
        add("pasterdream.seniors_dream.entry.chaos.page0", "A buff applied to enemies by some weapons and items. Its effects are:$(br)When the player is under Confusion, their vision shakes similarly to the \"Insanity\" effect.$(br)When other creatures are under Confusion, their facing changes randomly, and they are pressed to the ground, briefly losing the ability to act.");
        add("pasterdream.seniors_dream.entry.sculk_armor", "Sculk Echo");
        add("pasterdream.seniors_dream.entry.sculk_armor.page0", "This buff is obtained when the player wears a full Sculk Echo armor set. Its effects are:$(br)Max health +4;$(br)When the player is in an environment with Y<0, green particles appear around them and they gain Resistance.");
        add("pasterdream.seniors_dream.entry.sculk_armor.page1", "Immune to the sculk's dark dread;$(br)When under Darkness, instead gain Speed II and Resistance II for 1 minute;$(br)Wardens will not attack players with this buff.");
        add("pasterdream.seniors_dream.entry.dyedream_armor", "Dyedream Protection");
        add("pasterdream.seniors_dream.entry.dyedream_armor.page0", "This buff is obtained when the player wears a full Dyedream armor set. Its effects are:$(br)Max health +4;$(br)Gain Absorption I every 30 seconds;$(br)Gain a Dyedream tool enhancement: Dyedream Alloy tools and Melt Dream Crystal tools deal +50%% damage.");
        add("pasterdream.seniors_dream.entry.dream_wish", "Dream Wish");
        add("pasterdream.seniors_dream.entry.dream_wish.page0", "A buff obtained after drinking Dream Juice. Its effect is:$(br)While under this buff, sleeping will take you to the Dyedream World.");
        add("pasterdream.seniors_dream.entry.shadow_silence", "Shadow Silence");
        add("pasterdream.seniors_dream.entry.shadow_silence.page0", "Usually a debuff the player inflicts on monsters, temporarily disabling the special skills of Shadow Creatures. In special cases, even some of the most powerful Shadow Creatures seem to be silenced?");
        add("pasterdream.seniors_dream.entry.bind", "Bind");
        add("pasterdream.seniors_dream.entry.bind.page0", "Usually a debuff the player inflicts on monsters. While under this effect, the creature cannot move.");
        add("pasterdream.seniors_dream.category.dyedream_world", "The Dyedream World");
        add("pasterdream.seniors_dream.category.dyedream_world.desc", "The dream of origins. Beyond the Dyedream Rift lies a pink world of drifting petals — a maiden's most exquisite fantasy made real. This is the first stop of your dream journey, Dreamseeker.");
        add("pasterdream.seniors_dream.category.dyedream_world_items", "Blocks & Items");
        add("pasterdream.seniors_dream.category.dyedream_world_items.desc", "Items in the Dyedream dimension.");
        add("pasterdream.seniors_dream.category.dyedream_world_structures", "Structures");
        add("pasterdream.seniors_dream.category.dyedream_world_structures.desc", "Structures in the Dyedream dimension.");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_chest", "Melt Dream Crystal Chest");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_chest.page0", "While exploring the structures of this dream, you will often find these exquisite little chests. Simply interact with them and the chest opens on its own. You may notice that the more times the chest vibrates, the better the loot inside. Perhaps you should find a way to become luckier before opening one.$(br2)It is said there is a special tool in the dream that can gather the Dyedream power from you and refill opened Melt Dream Crystal Chests with treasure...");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_chest.page1", "--Melt Dream Crystal Chests won't turn into mimics, and there are no teleportation traps. Open them with peace of mind.");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_fragment", "Melt Dream Crystal Fragment");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_fragment.page0", "Crystals condensing immense dream power are scattered across the dream — in the Dyedream Worldtree, on the Dream Train, and so on. Of course, these fragments can occasionally be found in certain chests as well.$(br2)These fragments can not only be set into Dyedream Alloy tools to upgrade them into Melt Dream tools, but can also be placed down as a small crystal-cluster entity. Perhaps you'll need them to touch the profound darkness within the dream...");
        add("pasterdream.seniors_dream.entry.melt_dream_crystal_fragment.page1", "--A crystal fragment brimming with immense energy. It seems it can be used to better harness the power of dreams... or...");
        add("pasterdream.seniors_dream.entry.qym_doll", "QYM Doll");
        add("pasterdream.seniors_dream.entry.qym_doll.page0", "Sometimes, when you open a Melt Dream Crystal Chest, you find one of these soft dolls. Designed after the very first dream-seeking maiden, its adorable appearance lets you relax around it, effectively easing your mental strain.$(br2)Of course, you can also interact with the doll (pet it); each interaction eases your mental strain a little.");
        add("pasterdream.seniors_dream.entry.qym_doll.page1", "--What is this? So cute! Pet it.");
        add("pasterdream.seniors_dream.entry.galaxy_jelly", "Galaxy Jelly");
        add("pasterdream.seniors_dream.entry.galaxy_jelly.page0", "After eating this strange little jelly, you'll shoot into the sky with a \"whoosh\". Don't worry about falling to your death — it grants Slow Falling, ensuring a safe landing. All in all, it's an essential companion for exploring the dream, over hill and dale.$(br2)Note: eating it consecutively is strictly forbidden, lest you risk falling to your death.");
        add("pasterdream.seniors_dream.entry.galaxy_jelly.page1", "--Looking up at the sky, one can't help but marvel at the vast mystery of the star river. I may not be Chang'e, able to leap to the moon in one step, but I am willing to become Wan Hu, walking the path of chasing the stars.");
        add("pasterdream.seniors_dream.entry.life_crystal", "Life Crystal");
        add("pasterdream.seniors_dream.entry.life_crystal.page0", "When you enter the Dream Train or the Life Crystal Cavern, you may notice these heart-shaped crystals. Interacting with one increases your max health — though sadly, each one can only be used once. The good news is that these crystals can be mined and carried away; once you find more, consider taking them home as decorations. However, it seems the effect of Life Crystals fades with your deaths...");
        add("pasterdream.seniors_dream.entry.life_crystal.page1", "--Heart Breaker");
        add("pasterdream.seniors_dream.entry.machine_light_wing", "Machine Light Wing");
        add("pasterdream.seniors_dream.entry.machine_light_wing.page0", "When you curiously equip these wings obtained from Melt Dream Crystal Chests, they immediately absorb your Melt Dream Energy and lift you into the air, continuously maintaining your flight. Unless your energy runs out or you take them off, they won't let you set foot firmly on the ground.$(br2)Though everyone wants a pair of wings, these Light Wings drain energy far too quickly — better save them for when they're truly needed.");
        add("pasterdream.seniors_dream.entry.machine_light_wing.page1", "--Clover: Your feet have left the ground, right?");
        add("pasterdream.seniors_dream.entry.qym_armor_set", "QYM Armor Set");
        add("pasterdream.seniors_dream.entry.qym_armor_set.page0", "These are the personal belongings of the maiden who once sought dreams. When you wear them, a dreamlike sensation flows through your body — you may stay awake forever, gain inexhaustible Melt Dream Energy, or soar freely through the sky.");
        add("pasterdream.seniors_dream.entry.qym_armor_set.page1", "And when you wear the full set, you will automatically dodge all attacks aimed at you within the dream. However, if you walk the earth as a mere mortal, you cannot obtain this predecessor Dreamseeker's belongings — you may need the divine power capable of creating all things...$(br2)--The first dream-seeking maiden sleeps within a long rainbow, awaiting later dreamers to explore the unknown.");
        add("pasterdream.seniors_dream.entry.pale_boneneedle", "Pale Boneneedle");
        add("pasterdream.seniors_dream.entry.pale_boneneedle.page0", "On the snowy mountains, you find a pale snow lotus with a strong fragrance — a scent with a distinctly refreshing effect. As a Dreamseeker who once lost themselves in dreams, you hit upon a clever idea: bind the pale snow lotus's corolla to a bone needle. The intense pain and the stimulating scent should quickly wake you and pull you out of the dream.$(br2)And if you blend an Ender Pearl and an echo from the ancient city into the Pale Boneneedle, perhaps wonders will follow...");
        add("pasterdream.seniors_dream.entry.pale_boneneedle.page1", "--Whether the dream is a clean Dyedream or a profound shadow, when the dream ends, we shall meet again.");
        add("pasterdream.seniors_dream.entry.dyedream_perfume", "Dyedream Perfume");
        add("pasterdream.seniors_dream.entry.dyedream_perfume.page0", "In the Dyedream, the plants on the ground catch your attention — their fragrance sparks a new idea: perhaps you could gather them and turn them into perfume...$(br2)After drinking this peculiar beverage, Phantoms won't pester you for a while, and the power of the dream makes you feel as if you've had a good night's sleep — for the next few days, no Phantom will buzz above your head like a fly...");
        add("pasterdream.seniors_dream.entry.dyedream_perfume.page1", "--Q: Why drink perfume? A: You're already dreaming — don't worry about such trivial matters~");
        add("pasterdream.seniors_dream.entry.terra_blade", "Terra Blade");
        add("pasterdream.seniors_dream.entry.terra_blade.page0", "When you have gathered the eight swords forged from ancient relics in reality and the inferno, you may realize there is another way to make them shine...$(br2)These eight swords, fused with the springs of the dream, become the divine blade — the Terra Blade, with supreme damage and formidable power. When your Melt Dream Energy is full, you can activate the sword-qi state: every slash releases deadly sword-qi to slay distant foes. Of course, always keep an eye on your Melt Dream Energy...");
        add("pasterdream.seniors_dream.entry.terra_blade.page1", "--Forged by heaven into a single sword, eight blades as one, cast into the hero's blade.");
        add("pasterdream.seniors_dream.entry.milky_way_jelly", "Milky Way Jelly");
        add("pasterdream.seniors_dream.entry.milky_way_jelly.page0", "Perhaps one day you will need to cross, as a mere mortal, natural barriers that ordinary means cannot breach, and reach the top of the world. The Galaxy Jelly from the Dyedream World doesn't quite perform well enough, so you turn your eyes to the clouds of the Dyedream World and the feathers of reality...");
        add("pasterdream.seniors_dream.entry.milky_way_jelly.page1", "After eating this brand-new jelly, a force sends you to the top of the world and grants you Slow Falling, letting you descend gently. In this way, certain barriers that are hard to cross will no longer stop you.$(br2)--When the earth is no longer an obstacle for humanity, the sea of stars becomes our goal.");
        add("pasterdream.seniors_dream.entry.dream_fertilizer", "Dream Fertilizer");
        add("pasterdream.seniors_dream.entry.dream_fertilizer.page0", "After discovering the unique Pink Slimes in this dream, you should find a way to obtain pink slimeballs from them, and try grinding the pink slimeballs together with bone meal blocks — it seems you can get a kind of mud...$(br2)This mud has a strong ripening effect on any crop, even those grown in dreams. It is born of the dream, so it is named Dream Fertilizer. May it bless your crops with vigorous growth.");
        add("pasterdream.seniors_dream.entry.dream_fertilizer.page1", "--At least the Pink Slime won't bless you... but the slimeball was taken from its body, so it can be considered the Pink Slime blessing your crops.");
        add("pasterdream.seniors_dream.entry.dream_accumulator", "Dream Accumulator");
        add("pasterdream.seniors_dream.entry.dream_accumulator.page0", "In the underground laboratory, you can find this compact device. It slowly gathers the surrounding air, letting it sink to the bottom of the pool; it seems to need some time. Yet in the predecessor's laboratory, there is also an adsorbent material. After adding it to the device, the dust in the air condenses around it at a much faster rate. This dust eventually condenses into Dyedream Dust, an important crafting material.$(br2)After bringing the device back to the real world, its efficiency drops considerably, but it can still slowly capture the dream energy of reality. Slow as it is, it's better than nothing.");
        add("pasterdream.seniors_dream.entry.dream_notes_dyedream_world", "Dreamseeker Notes");
        add("pasterdream.seniors_dream.entry.dream_notes_dyedream_world.page0", "You are not the first Dreamseeker to enter the dream; many predecessors stepped into it before you. In every corner of the dream, you can find notes they left behind. Some were written by their own hands; others are dreams manifesting their experiences into words. Some notes are merely their thoughts or musings, but others record the deeper secrets of the dream.$(br2)If you wish to pursue the mysteries of the dream further, perhaps you should search out these notes and read them carefully?");
        add("pasterdream.seniors_dream.entry.dyedream_church", "Dyedream Church");
        add("pasterdream.seniors_dream.entry.dyedream_church.page1", "While exploring the Dyedream World, you may find these mysterious churches floating in the sky. Inside, you can find a Melt Dream Crystal Chest, and on the lectern, casual notes from predecessor Dreamseekers. Perhaps you should carefully inspect every nook and cranny of the church — you never know what pleasant surprises await...");
        add("pasterdream.seniors_dream.entry.dyedream_church.page2", "--Who built these churches, and what religion do they follow? The answer awaits later Dreamseekers to discover...");
        add("pasterdream.seniors_dream.entry.dream_train", "Dream Train");
        add("pasterdream.seniors_dream.entry.dream_train.page1", "In the dream, you may sometimes hear the roar of a train — that is the Dream Train. When you hear its sound, the general location of the train flashes naturally through your mind. You can board this dreamlike train and explore its hidden mysteries...$(br2)If conditions permit, perhaps you should explore the train from front to back completely?");
        add("pasterdream.seniors_dream.entry.dream_train.page2", "--The whistle of the dream-chasing train resounds across the horizon; our journey continues.");
        add("pasterdream.seniors_dream.entry.dyedream_worldtree", "Dyedream Worldtree");
        add("pasterdream.seniors_dream.entry.dyedream_worldtree.page1", "In the plains of the Dyedream World grows a towering tree — a region where Melt Dream Energy is densest, with numerous Melt Dream Crystal Chests to be found. Legend says the Worldtree's pods have wondrous effects. You should explore boldly, unbound by trivialities — perhaps that way you'll uncover even more secrets...$(br2)Legend has it that in the beginning there were two worldtrees, one real and one false, but now only the real one remains. When you cannot find the Worldtree, perhaps think of the one who first created this dream...");
        add("pasterdream.seniors_dream.entry.dyedream_worldtree.page2", "--A worldtree linking heaven and earth, upholding the beauty of the entire dream.");
        add("pasterdream.seniors_dream.entry.dyedream_laboratory", "Dyedream Laboratory");
        add("pasterdream.seniors_dream.entry.dyedream_laboratory.page1", "In the Dyedream plains, you will find these ruins of the predecessors. Unremarkable from the outside, yet a whole different world lies within...");
        add("pasterdream.seniors_dream.entry.dyedream_laboratory.page3", "It seems these were the predecessor Dreamseekers' attempts at some experiment; the device called the Dream Accumulator seems to be the final result of their trials. As for why they left, that remains unknown...");
        add("pasterdream.seniors_dream.entry.dyedream_laboratory.page4", "--Here, Dreamseekers harnessed the power of dreams — a great stride toward uncovering the truth of the dream...");
        add("pasterdream.seniors_dream.entry.melt_dream_liquid_well", "Melt Dream Liquid Well");
        add("pasterdream.seniors_dream.entry.melt_dream_liquid_well.page1", "In the plains of the Dyedream World, wells like this are sometimes scattered about. Perhaps you should take a leap and dive to the bottom yourself to find out...");
        add("pasterdream.seniors_dream.entry.melt_dream_liquid_well.page3", "What flows in these wondrous wells is not ordinary clear water, but a mysterious liquid that keeps shifting colors. This liquid is saturated with Melt Dream Energy. You can try to follow in the predecessor Dreamseekers' footsteps and find a way to put it to use...");
        add("pasterdream.seniors_dream.entry.melt_dream_liquid_well.page4", "There may also be some chests tucked away in the wells' little corners — search actively.");
        add("pasterdream.seniors_dream.entry.melt_dream_liquid_well.page5", "--Flowing light shimmers quietly at the bottom of the well, illuminating the creatures beneath.");
        add("pasterdream.seniors_dream.entry.dyedream_tavern", "Dyedream Tavern");
        add("pasterdream.seniors_dream.entry.dyedream_tavern.page1", "These small taverns exist in the Dyedream World. Built by unknown hands, they provide weary dream travelers a place to rest.");
        add("pasterdream.seniors_dream.entry.dyedream_tavern.page2", "The chests upstairs seem to hold items left by the predecessors — feel free to take them as supplies for your exploration. Downstairs, there are not only rich ores, but also scrolls recording the two predecessor Dreamseekers' myth-rivaling attempts...");
        add("pasterdream.seniors_dream.entry.dyedream_tower", "Dyedream Tower");
        add("pasterdream.seniors_dream.entry.dyedream_tower.page1", "In the Dyedream, these soaring spires easily catch your eye. They come in two architectural styles, and in the bottom room of each tower you can find the travelogues of earlier visitors...$(br2)Speaking of towers, climbing to the top seems an essential step. There should be some loot at the top — perhaps you should search carefully? Though, depending on the tower's style, the loot's location may differ...");
        add("pasterdream.seniors_dream.entry.dyedream_tower.page2", "--Climb to the top → synchronize viewpoint → leap of faith → bang! Synchronization failed~");
        add("pasterdream.seniors_dream.entry.dyedream_floating_temple", "Dyedream Floating Temple");
        add("pasterdream.seniors_dream.entry.dyedream_floating_temple.page1", "In the skies of the Dyedream World, buildings like this float among the clouds. This classical-era temple moves all who enter with its sacred solemnity. Inside, you will find a Melt Dream Crystal Chest and a scroll left by the predecessors...");
        add("pasterdream.seniors_dream.entry.dyedream_floating_temple.page2", "--When temples float in the Dyedream sky, even the gods linger in the misty dream.");
        add("pasterdream.seniors_dream.entry.invaded_church", "Infested Church");
        add("pasterdream.seniors_dream.entry.invaded_church.page1", "");
        add("pasterdream.seniors_dream.entry.invaded_church.page2", "While exploring the Dyedream World, you may occasionally spot in the sky a church half-blackened by the shadow and darkness of another dream. Melt Dream Crystal Chests can be found within this shadow-infested church, and if you search the corners carefully, you may find some lost chests.");
        add("pasterdream.seniors_dream.entry.invaded_church.page3", "Moreover, notes left by predecessor Dreamseekers exist here. Follow the notes' guidance to the Nether, find a way through the bedrock layer, and perhaps you'll find the source of the darkness...$(br2)--A church eroded by shadows, hiding in its depths ill omens and madness.");
        add("pasterdream.seniors_dream.entry.fluffy_wind_church", "Fluffy Wind Church");
        add("pasterdream.seniors_dream.entry.fluffy_wind_church.page1", "While exploring the Dyedream World, you may occasionally spot in the sky a church half-dyed verdant by the moss and gentle breeze of another dream. Melt Dream Crystal Chests can be found within this breeze-wreathed church. Search carefully, and you may also find some lost chests in the corners.");
        add("pasterdream.seniors_dream.entry.fluffy_wind_church.page2", "Upon the lectern at the center of the church lies a Dreamseeker's Eternal Scroll, from which you can obtain the notes of the first Dreamseeker. Perhaps, following the notes, eating the Queer Soup and soaring high into the sky will carry you into the other dream that dyed this church verdant?$(br2)--A church wreathed in verdure and breeze, harboring a dream that yearns to fly.");
        add("pasterdream.seniors_dream.category.lamp_shadow_world", "Under the Lamp Shadow");
        add("pasterdream.seniors_dream.category.lamp_shadow_world.desc", "The stronger the sunlight, the deeper the shadow. This is another world — corruption, madness, assimilation: all are the Dreamseeker's fate. Yet the remaining words in the ruins seem to hide more unknowns. When you stand before that darkness, what will you choose?");
        add("pasterdream.seniors_dream.category.lamp_shadow_world_items", "Blocks & Items");
        add("pasterdream.seniors_dream.category.lamp_shadow_world_items.desc", "This chapter introduces some blocks and items under the Lamp Shadow.");
        add("pasterdream.seniors_dream.category.lamp_shadow_world_structures", "Structures");
        add("pasterdream.seniors_dream.category.lamp_shadow_world_structures.desc", "Structures under the Lamp Shadow.");
        add("pasterdream.seniors_dream.entry.brooch_of_white_orchid", "Brooch of White Orchid");
        add("pasterdream.seniors_dream.entry.brooch_of_white_orchid.page0", "When you choose the light in the darkest dream and defeat the great hand coiled in the deep shadow, you can obtain this marvelous brooch. The power of light it holds keeps you clear-headed in environments that drive people mad. If you wield a White Sword while wearing it, the sword seems to become even more deadly...");
        add("pasterdream.seniors_dream.entry.brooch_of_white_orchid.page1", "--Walk in darkness, serve the light.");
        add("pasterdream.seniors_dream.entry.white_sword", "White Sword");
        add("pasterdream.seniors_dream.entry.white_sword.page0", "When you pledge allegiance to the light, a glowing crystal appears in your pocket. With it, you can forge the White Sword, which holds the power of light. This sword deals formidable damage, and its light-affinity makes it especially effective against Shadow Creatures, applying a \"Silence\" effect to them.");
        add("pasterdream.seniors_dream.entry.white_sword.page1", "Furthermore, while holding this sword, you can unleash a Combat Art — \"White Sword Rain\". Not only does it bring devastating ruin to foes, it also briefly binds its victims. If you are close enough to an enemy and looking at them, White Sword Rain can even track them; ordinary slashes may also release tracking sword-rain...");
        add("pasterdream.seniors_dream.entry.white_sword.page2", "--I bear no hatred toward the wretches steeped in darkness; I simply must execute the justice of light upon them as soon as possible. As soon as possible.");
        add("pasterdream.seniors_dream.entry.seal_of_the_corrupted", "Seal of the Corrupted");
        add("pasterdream.seniors_dream.entry.seal_of_the_corrupted.page0", "When you choose to embrace the shadow in the endless darkness and slay the great hand lurking within it, this seal becomes yours. While wearing it, your madness brings no negative effects, and the monsters of the shadows regard you as one of their own, remaining neutral toward you. When you fall completely into madness, the dark monsters spawned will not attack you; instead, they will vent their hatred upon your enemies.");
        add("pasterdream.seniors_dream.entry.seal_of_the_corrupted.page1", "--All things shall sink into profound madness, and I must become the envoy of the shadow.");
        add("pasterdream.seniors_dream.entry.shadow_sword", "Shadow Sword");
        add("pasterdream.seniors_dream.entry.shadow_sword.page0", "After deciding to fall into the darkness, you obtain a broken sword hilt. With it, you can forge the deepest, darkest Shadow Sword. This sword ceaselessly erodes your sanity. The deeper you sink into the mire of madness, the deadlier it becomes — and when your last shred of reason is devoured, you will have to nourish it with your own health...");
        add("pasterdream.seniors_dream.entry.shadow_sword.page1", "While holding this sword, you can sacrifice sanity to turn its next strike into a \"Nightmare Slash\", making that strike deadlier — its damage depends on your reason.");
        add("pasterdream.seniors_dream.entry.shadow_sword.page2", "Please note: this sword will not serve those who betray the shadow by using divine power to never go mad (turning off the SAN system with commands).");
        add("pasterdream.seniors_dream.entry.shadow_sword.page3", "--What is called sanity is but a mortal lie; I shall use madness to bring all beings an equal final night.");
        add("pasterdream.seniors_dream.entry.shadow_blast_furnace", "Shadow Blast Furnace");
        add("pasterdream.seniors_dream.entry.shadow_blast_furnace.page1", "In the shadowy dream, you find the experimental remains of QYM and Yelan. Among the ruins lie the wreckage of this device and a blueprint; following the blueprint, it seems you can recreate the machine.$(br2)Fuelled by molten shadow and nightmares from the dream, this machine can transform certain items, dyeing them with shadow. Moreover, it seems it can also be used to repair rusted metal...");
        add("pasterdream.seniors_dream.entry.shadow_blast_furnace.page2", "--A machine that smelts darkness, determined to dye all things in darkness.");
        add("pasterdream.seniors_dream.entry.broken_note", "Broken Note");
        add("pasterdream.seniors_dream.entry.broken_note.page0", "Not a few outsiders have visited this dream, but more of their notes were torn to shreds and scattered across the dream's corners. To piece together and decipher these notes, we need a dedicated facility.$(br2)By restoring these notes, you can learn more secrets — perhaps even the ways to repair certain facilities.");
        add("pasterdream.seniors_dream.entry.broken_note.page1", "--Knowledge is power, all the more so in such a perilous dream.");
        add("pasterdream.seniors_dream.entry.black_metal_ingot", "Black Metal Ingot");
        add("pasterdream.seniors_dream.entry.black_metal_ingot.page0", "QYM and Yelan long studied the reuse of the rusted metal found everywhere under the Lamp Shadow. After reading the notes she left, you have an idea for recreating this technique...$(br2)Following the idea recorded in her notes — \"filling the gaps with shadow\" — and with the aid of the Shadow Blast Furnace, you successfully craft Black Metal Nuggets. This metal can be used to forge shadow-eroding tools. But a few nuggets are clearly not enough; you must find a way to obtain ingots suitable for forging...");
        add("pasterdream.seniors_dream.entry.black_metal_ingot.page1", "--A metal that flows with shadow — a small step for Dreamseekers in harnessing the power of darkness.");
        add("pasterdream.seniors_dream.entry.calais_spice_bottle", "Calais Spice Bottle");
        add("pasterdream.seniors_dream.entry.calais_spice_bottle.page0", "Under the Lamp Shadow, you can find a spice bottle left by a predecessor. While wearing it, you eat faster, and it grants you the \"Calais Spice\" effect: each attack thereafter consumes one stack of \"Calais Spice\" and randomly grants an effect. If the \"Calais Spice\" effect runs out, you'll need to eat to restore hunger and regain \"Calais Spice\".");
        add("pasterdream.seniors_dream.entry.bright_butterfly_curio", "Bright Butterfly Curio");
        add("pasterdream.seniors_dream.entry.bright_butterfly_curio.page0", "In the past, the first Dreamseeker to enter the Lamp Shadow mastered the power of the shadows with the Bright Butterfly and finally left it behind. Now that you command the power of light, perhaps you can try modifying the Light Butterfly Curio with a White Crystal...$(br2)Once you reproduce the Bright Butterfly with a White Crystal and wear it, light dwells in your eyes forever, and the darkness before them disperses. Any means that seeks to rob you of the light in your eyes will fail.");
        add("pasterdream.seniors_dream.entry.bright_butterfly_curio.page1", "--When all you see is light, darkness naturally has nowhere to hide.");
        add("pasterdream.seniors_dream.entry.shadow_foundry", "Shadow Foundry");
        add("pasterdream.seniors_dream.entry.shadow_foundry.page0", "Past Dreamseekers struggled through this dark land, leaving behind many remnants. Among them, this ruin is what remains of QYM and Yelan's research on rusted metal.$(br2)Here, you can find a blueprint for the Shadow Blast Furnace and its wreckage. Perhaps you could try rebuilding this machine elsewhere and use it to reproduce QYM's research results...");
        add("pasterdream.seniors_dream.entry.shadow_foundry.page1", "--Humans never cease pursuing the unknown, even in the eternal dark dream — this ruin is the best proof...");
        add("pasterdream.seniors_dream.entry.shadow_dungeon_structure", "Shadow Dungeon Structure");
        add("pasterdream.seniors_dream.entry.shadow_dungeon_structure.page0", "Unfinished");
        add("pasterdream.seniors_dream.entry.aaroncos_arena_portal", "The Strange Hand Structure");
        add("pasterdream.seniors_dream.entry.aaroncos_arena_portal.page0", "While exploring under the Lamp Shadow, you may sometimes find these hand-like structures, with a white rift like a portal in their palms.$(br2)Yet when you try to stand in the rift of its palm, nothing happens.$(br2)Perhaps the time is not yet right. Let us continue our journey through the dream — one day, this place will show you all its secrets.");
        add("pasterdream.seniors_dream.entry.aaroncos_arena", "Aaroncos Arena");
        add("pasterdream.seniors_dream.entry.aaroncos_arena.page0", "After you make your choice between light and shadow, you finally earn the right to pass through the portal and witness the utterly dreadful Hand of Shadow. This place erodes your sanity, gradually putting you at a disadvantage as the battle wears on.$(br2)Whether you choose to become a lamp to destroy it and prevail, or to merge with the shadow to accept it and replace it, this battle is an unprecedented nightmare. Make sure you are fully prepared before challenging it.");
        add("pasterdream.seniors_dream.category.wind_journey", "Wind Journey");
        add("pasterdream.seniors_dream.category.wind_journey.desc", "At the end of the sky lie seas of clouds and wind-wreathed islands. Balloons, dolls, and floating isles all bid you: slow down, and go with the wind.");
        add("pasterdream.seniors_dream.category.wind_journey_items", "Items");
        add("pasterdream.seniors_dream.category.wind_journey_items.desc", "This chapter introduces some items of the Wind Journey.");
        add("pasterdream.seniors_dream.category.wind_journey_structures", "Structures");
        add("pasterdream.seniors_dream.category.wind_journey_structures.desc", "This chapter introduces some structures of the Wind Journey.");
        add("pasterdream.seniors_dream.entry.wind_direction", "Wind Direction");
        add("pasterdream.seniors_dream.entry.wind_direction.page0", "In this world held aloft by the wind, powerful air currents greatly affect your exploration. Each morning, the wind may change direction, keeping that course until the next morning.$(br2)When traveling with the wind, whether running, jumping, or using Blink, you move faster and farther; but going against the wind, you'll be greatly hindered.");
        add("pasterdream.seniors_dream.entry.wind_direction.page1", "Therefore, when exploring here, following the wind seems the wise choice. You can also craft a Wind Vane — it helps you see the wind direction and your current position.");
        add("pasterdream.seniors_dream.entry.wind_runner_jelly", "Wind Runner Jelly");
        add("pasterdream.seniors_dream.entry.wind_runner_jelly.page0", "A jelly unique to the Wind Journey — and what's more, it can be crafted?!$(br2)If you add a bit of sweetness to jellyfish jelly, along with the crystals condensed from the islands and wind, plus some plant extract, and grind them all together...");
        add("pasterdream.seniors_dream.entry.wind_runner_jelly.page1", "Wind Runner Jelly lets you glide with an Elytra even without equipping elytra-type gear — though some wings' boost and creative flight functions still can't be replicated.$(br2)--Wait, you can't fly? Then how did you get to this dream?");
        add("pasterdream.seniors_dream.entry.break_wind_curtain", "Break Wind Curtain");
        add("pasterdream.seniors_dream.entry.break_wind_curtain.page0", "While flying through the clouds, you will find these teal \"membranes\". No need to worry — hitting one doesn't hurt, though you can indeed \"feel the kinetic energy\". A Break Wind Curtain grants you an extra burst of flight energy and a brief speed boost; pass through several and leaping over the clouds is no trouble at all.$(br2)Of course, this fine thing can be crafted with items imbued with dream power and wind power.");
        add("pasterdream.seniors_dream.entry.break_wind_curtain.page1", "--What do you mean you hit the frame of the Break Wind Curtain?");
        add("pasterdream.seniors_dream.entry.christmas_tree_island", "Christmas Tree Island");
        add("pasterdream.seniors_dream.entry.christmas_tree_island.page0", "This is an island that seems not to belong here — snow-covered year-round, wintry in all four seasons, with twinkling lights and bustling animals adding to its vitality.$(br2)Look around the island and you can't help but sigh: this place is dripping with wealth! The Christmas trees are even decorated with diamond blocks!$(br2)At the very center of the island, beneath the largest tree, are many chests. Inside lies a snow-white hairpin. This hairpin holds the breath of deep winter; wear it and even ice and snow will shield you from the agony of fire.");
        add("pasterdream.seniors_dream.entry.christmas_tree_island.page1", "--If those witches riding flying broomsticks could fly here for the hairpin, they wouldn't have to fear being burned to death.");
        add("pasterdream.seniors_dream.entry.break_wind_knight_altar", "Wind Knight Altar");
        add("pasterdream.seniors_dream.entry.break_wind_knight_altar.page0", "Above the Wind Moor Archipelago lies another sizable island — the Wind Knight Altar. The crumbling walls seem to tell of past fierce battles, and the present silence makes one sigh at the vicissitudes of time. At the center of the arena lies an Eternal Scroll; it seems QYM has already figured out how to awaken the knight.$(br2)To summon the Wind Knight, you need to insert the crystal buried on this island into the very center of the altar, assemble its torso and head with iron ingots imbued with gale power, and finally, a little lightning to activate it...$(br2)The Wind Knight will drive away all intruders. If you wish to challenge it, be fully prepared.");
        add("pasterdream.seniors_dream.entry.break_wind_knight_altar.page1", "--Turns out you have to assemble it yourself after all.");
        add("pasterdream.seniors_dream.category.story", "Story");
        add("pasterdream.seniors_dream.category.story.desc", "This chapter compiles the mod's story.");
        add("pasterdream.seniors_dream.entry.deposition_shadow", "Deposition Shadow");
        add("pasterdream.seniors_dream.entry.deposition_shadow.page0", "Deposited shadows, a ruined civilization, and the vitality that signifies death. The environment here feels oppressively stifling; I cannot find a single trace of color that belongs to this world. And there are many... creatures that defy common sense, like dreams detached from reality.");
        add("pasterdream.seniors_dream.entry.deposition_shadow.page1", "Deposition Shadow — the desolate Lamp Shadow World.");
        add("pasterdream.seniors_dream.entry.deposition_shadow.page2", "What's strange, though... these shadow-like creatures don't attack me, but those who travel with me aren't so lucky. And the jars and pots scattered here, the chains reaching to the sky, the bones everywhere... who built these? Or... are they merely my imagination...");
        add("pasterdream.seniors_dream.entry.lamp_shadow_travelogue_1", "Lamp Shadow Travelogue I");
        add("pasterdream.seniors_dream.entry.lamp_shadow_travelogue_1.page0", "Here are some records of exploring this place:");
        add("pasterdream.seniors_dream.entry.lamp_shadow_travelogue_1.page1", "Lamp Shadow Travelogue I — illustrations of exploration records.");
        add("pasterdream.seniors_dream.entry.lamp_shadow_travelogue_1.page2", "Defeating the black translucent monsters drops some... \"wriggling\" black gel.$(br)On certain tile-and-stone terrain there are pots and graves that yield good things.$(br)Some chains and ruins hold rusted metal — a metal that seems not to belong to any element of reality.$(br)Where mushrooms grow thick, there live beetles that love a certain local white flower; you can befriend them.$(br)Small lakes of liquid \"shadow\" flow across the surface of Deposition Shadow.");
        add("pasterdream.seniors_dream.entry.shadow_dungeon", "Shadow Dungeon");
        add("pasterdream.seniors_dream.entry.shadow_dungeon.page0", "Remember that strange ruin we found while exploring before — like a ritual enshrining something at its center. But when I reached out to touch it back then, nothing happened. Judging from its broken structure, it must have fallen into disrepair?");
        add("pasterdream.seniors_dream.entry.shadow_dungeon.page1", "But the Black Metal we recently refined is very similar in material to that core... and that glowing white lamp block in the middle — I should try to repair it. If I succeed... I'll record the repair method. Also... my gut tells me this ruin has more than the above-ground part... that bright core is like a lamp, and its existence gave birth to the shadows below.");
        add("pasterdream.seniors_dream.entry.deception", "Deception");
        add("pasterdream.seniors_dream.entry.deception.page0", "It did not trust me. It kept my shadow to restrain me — like a human, my shadow learned how I think, how I fight, gradually drawing closer to me. But it answers to the shadow, always following me, watching whether I've fulfilled the terms of the bargain.$(br)After reading Aaroncos's remaining manuscripts and the Book of Shadows, I tried to establish a new way of communicating with the shadow — one-sided.");
        add("pasterdream.seniors_dream.entry.deception.page1", "I succeeded! I deceived my shadow, and the shadow itself. Before fleeing, I laughed wildly — I swaggered out of this place right in front of the shadow.");
        add("pasterdream.seniors_dream.entry.bargain", "The Bargain");
        add("pasterdream.seniors_dream.entry.bargain.page0", "I walked deeper, my steps growing lighter, until I was drowned among this black water. Countless whispers surged in like seawater; the searing pain in my skull nearly knocked me out. The whispers gradually converged, until only one voice remained.$(br)\"Give me your power; in return, I can do anything for you — but not as your slave\"");
        add("pasterdream.seniors_dream.entry.bargain.page1", "At that moment, the whispers scattered into a hubbub, as if debating fiercely, then gathered again.$(br)\"The door\"$(br)Before I could even react to what that meant, I had already been kicked out of the Land of Darkness.");
        add("pasterdream.seniors_dream.entry.shattered", "Shattered");
        add("pasterdream.seniors_dream.entry.shattered.page0", "\"Shut up!! Everything I am now is because of him. How dare you still ask me to save him!\"$(br)\"Look at this face of mine — is it even human anymore?! What difference is there between me and those monsters outside? And do you know? No, you don't. It hurts. It really, truly hurts. I should throw you into the fire so you can feel it too!! I haven't had a single peaceful night's sleep in ten whole days.\"");
        add("pasterdream.seniors_dream.entry.shattered.page1", "\"As for Yinuo, why should I save her? I've been a fool just like...\"$(br)\"No, no! No!! It's all of you — you all deserve to die!!\"$(br)\"If it weren't for you, none of this would have happened. You — since you're so determined, then stay here forever. As for Aaroncos, I will break the seal myself and grind his bones to dust!\"");

        // ===== Dream Notes Books: full translation =====
        add("book.pasterdream.content.染梦裂隙", "Just this morning — I must set off now!\nThrough that black rift, I can see a world like a fairyland.\nJust like the changes it has caused to its surroundings, this is most likely a kind of infection.\nI must go at once to find out the truth. Rather than a dream born of coincidence, I prefer to believe this is fate.\nI thought I would pay a price for stepping into that rift on impulse, but at least for now it seems quiet and peaceful — like a beautiful dream kingdom of a maiden. So I take this place to be a world dyed by beautiful dreams.\nDream-dyed world — that is my summary of the scene before my eyes.\nNow I should go explore and have a look around. I hope it brings me more surprises. Wish me luck.\nBy QYM");
        add("book.pasterdream.content.染梦游记 其一", "In this world, a kind of pink crystal sprout grows underground in warm regions.\nCreatures like slimes have natural protective coloring; perhaps you can find them by the sounds they make.\nTreasures lurk in the vast oceans here.\nIn our world, some chests are hidden; maybe it's the same here?\nThere are also strange flower beds here that offer unique flowers to those who can solve their puzzles.\nSome underground caves may hold crystals that increase your vitality.\nIn some places here, special springs flow.\nThe Worldtree's interior also hides treasure...\nLuck is the key to finding treasures here.\nEverything I have seen feels strangely familiar... as if I have experienced... all of this before.\nBy QYM");
        add("book.pasterdream.content.染梦游记 其二", "Edible ores with a sweet taste can be found in the shallow underground.\nBesides this sweet ore, rare titanium metal can also be found underground, though its color blends with the environment, making it hard to spot.\nThe pink quartz minerals growing underground are excellent building materials!\nA fruit grows on the leaves of the Dyedream trees; we can turn it into a cake — it must taste wonderful!\nThere are native crops here that require a special mud fertilizer to ripen.\nGrinding Dyedream Dust together with bone meal can produce a special dye.\nAn underground research institute houses a device that can accumulate Dyedream Dust.\nBy QYM");
        add("book.pasterdream.content.染梦游记 其三", "Exploring here feels relaxing; even doing nothing lifts my mood.\nAfter so long exploring, I've discovered quite a few biomes — both temperate and cold when it comes to scenery.\nAnd yet, coral grows beneath this frozen ocean!\nAlso, it seems a train passes by from time to time; I wonder if it's an illusion...\nI also found some nice records in chests in some ruins~\nI found that the more times a Melt Dream Crystal Chest vibrates, the better the treasure inside.\nSome churches stand out — half of the building looks like something has invaded it...\nBy QYM");
        add("book.pasterdream.content.染梦教堂 其一", "A record for myself and for those who come later.\nIn this so-called \"world\", I actually found a huge building floating in the sky. I'm sure I wasn't seeing things! If you who come later can also see this book...\nI instinctively believed I was in a dream, yet everything I saw and heard was so real...\nWhen I managed to climb onto this great building, I could see what it was. It looked like a church? But there was no one inside. (Though, who would live in the sky?)\nThe candles seemed to have been burning for a long time, as if they would never go out. Sunlight streamed through the glass opposite the entrance, illuminating everything inside.\nUpon the altar was a beautiful floating crystal, radiating light in all directions... (I stared at it for a long time)\nI slowly approached the crystal, and suddenly, as if it sensed my presence, it fell to the ground on its own. (Of course I took such a fine thing, but maybe it will regrow when you come? Perhaps...)\nI held the crystal in my palm, and it seemed to speak to me... that ethereal voice sounded like the heartfelt prayers of other souls.\nI turned to the great window at the back of the church, closed my eyes, and made my own wish...\nOh, right, one more thing — I'm leaving this book right here!\nWhy, you ask? ...Because I want my story to remain in this world, that's all~\nBy QYM");
        add("book.pasterdream.content.染梦教堂 其二", "The day before yesterday, QYM suddenly told me a secret — she said she had entered a dream-like place, and kept insisting it was real?\nAt first I didn't believe her, but she kept insisting I follow her to that magical place to adventure, to make a wish at that so-called church.\nI refused several times, but in the end I couldn't talk her out of it, so I decided to follow her and see what her world and that wondrous church were really like.\nAfter I passed through that astonishing rift and saw the scenery before me, I even pinched my arm... Could all this really be real?\nI followed her to the church — blue soul lanterns and towering spires, a Gothic Western building. It's hard to imagine why there would be traces of human civilization here.\nI decided to climb the floating island bearing the church to find out.\nInside the church floated lit candles, and glowing lanterns stood by the pews, filling the church with mystery and unreality. I'm not sure whether my words mean anything, but I still want to record what I see and hear.\nI wandered the church for a long time, taking in the atmosphere. It was filled with a wonderful aura and an indescribable mystery. I can't explain why I feel this way, but I know some wondrous power dwells here.\nBecause... QYM slowly floated up into the air.\nSeeing my astonished look, she showed no surprise, naturally accepting the fact that she was floating. Pointing at the mysterious crystal hovering over the church desk, she said: \"I don't know why, but I feel it's what lets me fly.\"\nQYM stroked the crystal with practiced ease, and it naturally floated along with her palm.\nI looked at her, hesitating: \"QYM...\"\nShe turned to me: \"Hm? What is it?\"\nWell... never mind, I won't say it. I shook my head: \"Ah, nothing...\"\nI've decided to write down everything I experienced here into a book and leave it in the church, for those who come to this place later.\nBy Yelan");
        add("book.pasterdream.content.染梦教堂 其三", "\"Is this place... a little too wonderful? Yinuo\"\n\nShortly after entering, this thought suddenly crossed my mind. Yinuo said I was overthinking it. True enough — there are no monsters here; everything is full of life and vitality.\n\nBut when I tried divination, the three results all differed — meaning the scene I see is not the true scene.\n\n\"Where there is light, there is darkness; the stronger the light, the thicker the darkness\"\n\nAfter half a year of ceaseless exploration in the dream, I discovered this... church half-dyed in black.\n\nThis abrupt blackness appeared in a place it never should have. Suppressing my trembling body, I stepped into the church.\n\nBy Calais");
        add("book.pasterdream.content.染梦水晶球", "When I was little, I dreamed of living inside a glass ball — my own little world!\nHaving my own tiny ecosystem would be so cool, and being wrapped up in it would be even better~\nI don't really like those huge empty houses; in my eyes, having my own little world is far more interesting than a big house~\nJust lie here, cradled by clouds, gazing through the pink glass at the sun through the clouds...\nMm... mm~ Just like this... have a sleep...\nWish me sweet dreams~\nBy QYM");
        add("book.pasterdream.content.祈愿树", "This is a Wishing Tree!\nWell... as for why I call it a Wishing Tree... I don't actually know either.\nThe moment I came here, I seemed to instinctively know how to name every plant and tree.\nI can call out their names effortlessly, just by following my heart, even though there is no right answer at all.\nNow, besides the wishes I used to make on birthdays... I also want to know the truth of this dream.\nBut after I made this wish, the tree gave no response, and I felt no response from it either.\nSo, if you who come later have answers to my questions... please continue this note.\nBy QYM");
        add("book.pasterdream.content.温暖的“寒风”", "Cold or warm?\nThe purpose of this pretty little pavilion doesn't seem to be escaping the heat.\nThe temperature here is always comfortable. Calling this a frozen ocean is only because glaciers surround it, making it look \"cold\".\nAfter all, tropical coral grows beneath those glaciers, and there are adorable dolphins. It can't really be called a frozen ocean in the strict sense.\nMm... perhaps this can't be explained by scientific theory?\nOr perhaps this is some kind of geographic wonder?\nThese pavilions also differ in color — pink roofs in temperate regions, blue in cold ones.\n(Quite fitting for the local style~)\nThe undergrounds of temperate and cold regions also differ, spawning different crystal formations. Perhaps these crystals will be useful to us...\nBy QYM");
        add("book.pasterdream.content.粉顶蘑菇屋", "This is a place Yelan and I discovered with a completely different biome.\nAlthough I've seen islands full of mushrooms, seeing a plain full of pink mushrooms still stunned me.\n\"Such huge mushrooms could even serve as a house!\"\nThen... we really did find a giant mushroom house.\nIt was unbelievable; we stood before that exquisite mushroom house, dumbfounded for several minutes.\nYelan: \"So people really lived inside mushrooms in the past?\"\nQYM: \"Because we're dreaming, this is all perfectly normal, hahaha...\" I teased.\nI even accepted this fact so readily myself... my brain was overloaded, so I simply stopped thinking about it!\nAfterward, we explored the surrounding ecology and spent a night in the mushroom house.\nAs always, I'll leave this book here.\nIf you who come later find it, please don't eat the mushroom house! I'll come back to play sometime... maybe.\nBy QYM");
        add("book.pasterdream.content.融梦涌泉井", "So you've seen this? Then let me start from the beginning.\nWhen I first strolled here, I noticed the vegetation here grew differently from elsewhere.\nIn a relatively small area there were many different vegetation types, and the density was also fairly high.\nCompared to other places, that was indeed suspicious, so I bent down to study the soil here.\nFrom the surface, the soil layers looked no different, but the deeper I dug, the more I found that scooping up a handful of dirt would let a few tiny glowing specks trickle through my fingers.\nNaturally, I went to rally the troops. I went home, called on Yelan, and brought two handy shovels and her treasured Titanium pickaxe.\nThen we returned and started digging downward. The deeper we dug, the more tiny glowing specks we found in the soil.\nWe set up ladders and climbed down to the bottom. In a lush cave, a glowing spring was gushing forth. Perhaps this glowing spring is the sun sustaining the underground vegetation.\nMaybe the spring can keep glowing to provide light for the plants? But by scientific theory, nothing can glow endlessly... So we built this \"well\" with the materials at hand. When I left, I took a bottle of the spring water home for experiments. I hope my research goes well.\nAs for the rest, I'll leave it to you who come later.\n(Don't forget the well digger when you draw water — be sure to thank me! Hehe~)\nBy QYM");
        add("book.pasterdream.content.浮空岛日记", "How do you suppose these buildings and islands floating in the sky came to be?\nNature's handiwork? Or the work of those who came here before us...\nBy all logic, stones and dirt shouldn't be able to fly. How could nature create traces of human civilization, and how could humans construct all this beyond the laws of the world?\nUgh, thinking hard about these things makes my worldview collapse.\nBut there's no need to dwell on it~ Maybe, as my intuition tells me, all of this is just a dream.\nImagination is boundless — I could even make this island speak! Don't you think?\nBut one day, I will come to understand all of this...\nMay this journey become a memory I can never forget.\nBy QYM");
        add("book.pasterdream.content.落叶归根 裂荚归冠", "Vigorous giant tree, your branches and leaves are your children; when they wither, they fall beside your roots.\nOther plants cast off their pods at birth, abandoning the last shell their mother left them.\nBut you, with your topmost branches, hoist the pod high into the sky.\nWith roots and leaves you nourish it, letting it bask in the highest light — the light crowning the top of this world.\nEven after the pod has long fulfilled its purpose, it still uses these nutrients to build its own dream.\nAnd so I offer my wish to you, as a first-meeting gift.\nBy QYM");
        add("book.pasterdream.content.梦境漂泊", "In the ocean of dreams, I drift, unmoored.\nLike a lonely traveler, seeking unknown wonders.\nThe starry sky keeps me company; the earth is my bed.\nIn this sleeping realm, I dance with dreams.\nMist beneath my feet, the unknown ahead.\nWith all my heart, I feel the rhythm of every journey.\nThere is song in the wind, stories in the rain.\nEvery moment is a wonder of the dream.\nI am a drifting traveler, fearless and unafraid.\nIn the depths of dreams, I seek the truth of life.\nOnly to\nOn this endless journey, become my own legend.\nBy QYM");
        add("book.pasterdream.content.气泡生态球", "Just as I was rowing my wooden boat across the ocean, searching for the ruins floating in the sky, a wondrous sphere suddenly caught my eye during a break.\nThe sphere floated in the icy seawater, fish faintly visible through its transparent membrane. I dove in, carefully reached out to touch the membrane, and — after feeling a slight resistance — passed right through it.\nIncredibly, the inside of the sphere was quite warm, a stark contrast to the freezing ocean water that had just soaked me to the bone. I crouched and reached through the thick cloud blocks to feel around — sure enough, the water beneath was warm too. The tropical fish here were no specimens, and the vivid colors I'd seen from the boat were no illusion born of exhaustion.\nCarefully examining the interior, I couldn't help recalling the ecospheres I'd seen before. Was this marvelous bubble sphere built by beings beyond human intelligence, or naturally formed by this unbelievable world?\nI cannot know.\nBut at least the small fish drifting slowly here bear me no hostility, just like the other creatures of this world. I could sit here and rest a while before swimming back to my boat.\nWith that thought, I casually poked the bubble wall beside me with a wooden stick — and the surface erupted into violent ripples, nearly bursting, making my heart skip a beat. Indeed, I'd best be more careful next time. Such fragile bubbles can probably only exist in calm waters; the slightest disturbance might shatter them and let the seawater flood in.\nOn the blank title of my note, I wrote the name I gave this place — \"The Bubble Biome Sphere\".\nAfter all, it is as beautiful and fragile as a small ecosphere; best to disturb it as little as possible.\nBy Qianye");
        add("book.pasterdream.content.染梦实验室", "This is a dilapidated building — it seems I've found traces of predecessors in this dream.\nI can't be the only one who found this strange, pink-filled place, but when I called out loudly, no one answered. The people have already left.\nDim lamplight enveloped the interior of the ruin, at the center of which stood a trapezoidal unknown device.\nI'm convinced this place is the laboratory of a predecessor who arrived here earlier, and that the device at its center is the final fruit of their research.\nRegrettably, I couldn't discover why the predecessor left in such haste.\nNow, I should carry on their research with this damaged device.\nBy Huixing");
        add("book.pasterdream.content.来往于梦", "To those who come later:\nThis writing records what I have seen and heard here, along with some speculations. I don't know what kind of world this truly is.\nBut (crossed-out text) \"miracle\" — that's the only word I can use to describe the world before my eyes.\nPink everywhere, an eternally bright sky, and darkness that breeds no loathsome evil — like a dream. No, perhaps it IS a dream.\nThough raised on materialist education, facing a scene completely inexplicable by existing knowledge, I can't help but ask:\nCould there really be some kind of deity in this world? (And would such a deity be the idealist \"god\", or a higher \"existence\"?)\nStill, there are no small number of doubts here; everything is relative.\nSince such a beautiful world exists, is there a place completely opposite to it? Moreover, this world has a strange sense of unreality everywhere — everything is so real, yet every place feels alienating. (Somewhat like a lucid dream?)\nWho created this miracle, and who sustains it? (Oversees it?)\n§m-Large tracts of crossed-out text-\nPerhaps someone once stayed here (settled?), given the presence of smokers, flower pots, and bookshelves — objects full of the flavor of life.\nBut the owner has likely been gone a long time (strangely, most items look brand new, and the flowers on the windowsill are still alive).\nAs for this world, for now let me call it a \"dream\".\nMore conclusions await further exploration to verify; perhaps I need a more stable way to travel between reality and this \"dream\".\nBy Liuhua");
        add("book.pasterdream.content.染梦世界树", "While gazing at the scenery from afar, I spotted this towering giant tree at the edge of my vision. Standing at its base and looking up, the trunk soared into the clouds, its canopy barely visible.\nDigging the soil around the roots, I found its roots don't extend very far — hard to explain its extraordinary height.\nThe winding trunk formed a natural staircase that made climbing fairly easy, though some parts still required free-climbing. When I reached the top of the branches, I could see a small hollow inside.\nA glowing white spring flowed from the trunk's side, anomalous in every way — but compared to the wonder of this world itself, this sight was hardly enough to astonish me.\nBack under the tree, I began to ponder what enabled this tree to form and grow normally. On this, I made a conjecture:\nThis world belongs to some kind of dream, and the dream energy in its atmosphere is unevenly distributed.\nJust as atmospheric phenomena cause weather changes, this energy dissolved in the dream's air — Melt Dream Energy — should also be unevenly distributed.\nIn regions where Melt Dream Energy settles more, the energy condenses into physical forms, creating continents, sky islands, trees, and everything else in this world. And where Melt Dream Energy gathers in large amounts within a small area, the result is a Melt Dream Crystal Chest — which also explains why energy escapes when you open one.\nExtrapolating from this theory, at the center of this dream world — where Melt Dream Energy is most abundant — a colossal structure should form; and the rich energy would manifest as countless Melt Dream Crystal Chests accumulated within it.\nAt that thought, I turned to look back toward the giant tree. It may well be the Worldtree of this dream world — a place of concentrated Melt Dream Energy, a dreamland holding countless Melt Dream Crystal Chests.\nI ought to climb that tree again and explore its inner structure. My earlier fruitless search must mean I missed something...\nBy Jixing");
        add("book.pasterdream.content.代达罗斯之翼与浮空岛", "Daedalus' Wings and the Floating Island\nShortly after I left that giant tree in disappointment, Qianye caught up with me and interrupted my plan to explore anew.\n\"See those islands floating in midair? I want to go up and see if there's any treasure there.\" I suggested to Qianye.\nUnexpectedly, Qianye doused me with cold water: \"I think you've lost your mind. We can't fly — how would we get up there?\"\n\"About that... I have a bold idea...\"\nUnder Qianye's incredulous gaze, I took out the feathers dropped by those pink chickens I'd picked up along the way. Then I melted down the candles I'd found into wax and stuck the feathers together with it, working hard to craft two pairs of wings.\n\"So you want to be Icarus.\"\n\"No, I think I'll be Daedalus. After all, the sun here won't melt this wax. And how would we know without trying? After all...\"\nThings went surprisingly smoothly — though by all logic, humans can't fly with such wings; yet somehow, the wind here seemed to carry the wings, letting us fly with no effort. We easily reached the floating island I'd previously only been able to gaze up at.\nAfter landing on the island, Qianye dashed straight into that little house. I followed right behind, found a spot to sit down, and chatted with her.\n\n\"Come to think of it, this world is way beyond common sense.\" Qianye took off the wings and started checking whether they'd fallen apart.\n\n\"That's why I said this world must be some kind of dream or illusion.\nAfter all, I can't understand at all how these islands float in the air unharmed, and stay perfectly still when we step on them.\"\n\n\"This house too — though it obviously looks man-made, there are no signs of human habitation at all. Also, I still can't understand how this thing works.\" Qianye shook the wings in her hand and said.\n\"Don't be so serious — anything can happen in a dream.\"\nBy Jixing");
        add("book.pasterdream.content.星河果冻和浮空岛", "Galaxy Jelly and the Floating Island\nShortly after I left that giant tree in disappointment, Qianye caught up with me and interrupted my exploration plans. I think it's best to explain my plan to her now...\n\"See those islands floating in midair? I want to go up and see if there's any treasure there.\" I suggested to Qianye.\nUnexpectedly, Qianye doused me with cold water: \"I think you've lost your mind. We can't fly — how would we get up there?\"\n\"About that... I have a bold idea...\"\nUnder Qianye's incredulous gaze, I took out the jelly-like items I'd found searching through some buildings in this world.\n\"What's this?\"\n\"It's something I found in those buildings. Eating it seems to make you shoot 'whoosh' into the sky, so...\"\nShe caught on quickly: \"So you want to be Armstrong?\"\n\"No, I'm at most Wan Hu — this is just about reaching a floating island. Come on, let's try.\"\nThings went surprisingly smoothly — though in reality no such jelly exists that launches you into the sky when eaten, thank goodness for it; we easily flew to the floating island I'd previously only been able to gaze up at.\n-After landing on the island, Qianye dashed straight into that little house. I followed right behind, found a spot to sit down, and chatted with her.\n\"Come to think of it, this world is way beyond common sense.\" Qianye sat down too and began tidying her windblown hair.\n\"That's why I said this world must be some kind of dream or illusion. After all, I can't understand at all how these islands float in the air unharmed, and stay perfectly still when we step on them.\"\n\"This house too — though it obviously looks man-made, there are no signs of human habitation at all. Also, I still can't understand how this jelly lets us fly when we eat it.\"\n\"Don't be so serious — anything can happen in a dream.\"\nBy Jixing");
        add("book.pasterdream.content.融梦釜与融梦炼金术", "I wandered through that pink world for a long time, until I found that machine beneath the giant tree — my alchemy research made a breakthrough.\nBy deconstructing and analyzing the machine within the dream, I finally understood its operating principle: essentially, the machine uses the dream's special energy to perform alchemical synthesis — and that energy is most abundant in a certain shining spring in the dream: the Melt Dream Liquid Well.\nThe next and most crucial step: what could the Melt Dream spring water bring to the currently near-rigid alchemy? Researching this was the hardest and most tedious part. First, I needed a container that could hold this potion. Through constant experimentation, I settled on Titanium — extremely corrosion-resistant — and materials with better compatibility with the Melt Dream spring; I named it: the Elixir Bottle.\nFinding compatible materials also cost me some time. During experiments, I realized I'd underestimated the potential of the Melt Dream spring and this machine: when used with the machine, the Melt Dream spring water can extend the duration of potions that originally last a short time, and can even strengthen the potency of certain potions. The rigid alchemy of ancient tomes is nothing before this machine. But such a marvelous thing deserves a name, so I'll call it: the Dream Cauldron, and this alchemy I call Melt Dream Alchemy.\nBy Qinglan");
        add("book.pasterdream.content.探求秘辛", "In order to gather some necessary resources, I came to a desert after a long journey.\nSince the resources I sought were quite rare, I might have to stay for a while; so I managed to find a village on the desert's edge and built this little hut to live in.\nSetting out at sunrise each day and returning before sunset; chatting with the villagers at night or when sandstorms kept me indoors — this was my daily life in the desert.\nHalf a year passed in the blink of an eye. My daytime explorations made no progress, but my bonds with the villagers grew warmer by the day.\nThe adults were endlessly grateful that I protected them from monsters at night, while the children reveled in the adventure stories I shared from my travels — gradually, the villagers began to reveal \"secrets\" never told to other travelers:\n\"Our village blacksmith almost never leaves his home, so you've probably hardly seen him. They say he was once a royal craftsman of some kingdom, whose family forged all manner of elite weapons for the royal family; but after the kingdom fell, his family declined, and finally wandered here to settle. He still doesn't seem to accept his situation, and built his workshop a bit far from the village. We don't have much contact with him either, only work-related dealings... but if it's you, you should be able to get along with him...\"\nThe villagers seemed to want me to talk some sense into the reclusive, fallen forging aristocrat (though I suspect they just hope that once I get friendly with him, they can get their tools repaired at a cheaper price). So, bearing my aged vintage brew, I visited the blacksmith's workshop.\n...\nThough there were many twists and turns along the way, we eventually became close friends. During a drink together, I told the elderly smith that I hoped his family's exquisite forging skills would be passed on; though I'd learned much of his technique through our time together, I could never reproduce his skill on my own, nor forge equipment of such superior capability as he did.\nAfter a long silence, he took out paper and a pen, drew me a blueprint, and told me: only by strictly following his workshop's layout could one guide and gather some... substance? from the atmosphere to its fullest, thereby forging extraordinary and novel tools. Moved by his generosity and trust, I left behind almost all my valuables as thanks, and departed with this blueprint.\nBefore I knew it, I'd stayed in this desert for far too long...\nTime to set out on a new journey — when I next stop somewhere, I'll try building a workshop according to this blueprint.\nBy Jixing");
        add("book.pasterdream.content.研究笔记:黑金属", "To trace the origin of this research, I must go back to some strange metal I found in this pitch-dark dream.\nIt appears in those hanging lanterns, ruins, and some pottery jars and treasure boxes. Its texture looks like iron, but its rust isn't a brown peeling layer — rather, many small black holes.\nSmelting it in an ordinary furnace had no effect at all, so I simply threw it into lava — which, unsurprisingly, melted it straight away, merging it with the magma.\nTo study this metal, Yelan and I found a run-down trapezoidal building nearby.\nBy a stroke of luck, some dripping fluid shadow from the second floor fell into the jar holding this metal — and the shadow, as if conscious, filled the rusted holes by itself. \"This isn't enough,\" \"it seems this metal may just be a carrier; what's truly missing are those shadows.\"\nThrough continuous research, we arrived at the following formula: \"high heat, flowing shadow, and the bodies of those shadow monsters.\"\nWe woke up from here, brought some materials and equipment, and once again lay down on the bed heading under the Lamp Shadow...\nAmid the roar of the machine, and the fusing, melting, condensing... at last, a piece of black metal fell to the ground with a clang...\nBy QYM");
        add("book.pasterdream.content.灯影游记 其二", "I'm curious how these fungi manage to grow here?\nThere's no light in this sky, no familiar sun, no reliable source of energy — the soil here doesn't even seem able to provide nutrients.\nBut these fungi drive their hyphae into the black stone, growing into mushroom trees taller than a person, and even bearing glowing fruit.\nAt the same time, these plants nurture some possibly-local creatures? These beetles seem to feed on the fungi here, living here in droves.\nFacing the darkness, they seem to have evolved white eyes — perhaps that's how they've adapted to the dark.\nThese lifeforms together form a so-called \"ecosystem\"... which simply cannot be explained by modern science.\nBut then, from that pink-stained world to this pitch-black place crawling with monsters, it long ago stopped being explainable by science — it's entirely an illusory product of subjective imagination.\nSigh, I'm not a scientist anyway. But still... do you think these mushrooms... might be tasty?\nI think I should research some recipes. (And find a test subject!)\nBy QYM");
        add("book.pasterdream.content.沉淀阴影", "Deposited shadows, a ruined civilization, and the vitality that signifies death.\nThe environment here feels oppressively stifling; I cannot find a single trace of color that belongs to this world.\nAnd there are many... creatures that defy common sense, like dreams detached from reality.\nWhat's strange, though... these shadow-like creatures don't attack me, but those who travel with me aren't so lucky.\nAnd the jars and pots scattered here, the chains reaching to the sky, the bones everywhere... who built these? Or... are they merely my imagination...\nBy QYM");
        add("book.pasterdream.content.暗影地牢", "Remember that strange ruin we found while exploring before — like a ritual enshrining something at its center.\nBut when I reached out to touch it back then, nothing happened. Judging from its broken structure, it must have fallen into disrepair?\nBut the Black Metal we recently refined is very similar in material to that core... and that glowing white lamp block in the middle — I should try to repair it.\nIf I succeed... I'll record the repair method. And... my gut tells me this ruin has more than the above-ground part... that bright core is like a lamp, and its existence gave birth to the shadows below.\nBy QYM");
        add("book.pasterdream.content.灯影游记 其一", "Here are some records of exploring this place:\nDefeating the black translucent monsters drops some... \"wriggling\" black gel.\nOn certain tile-and-stone terrain there are pots and graves that yield good things.\nSome chains and ruins hold rusted metal — a metal that seems not to belong to any element of reality.\nWhere mushrooms grow thick, there live beetles that love a certain local white flower; you can befriend them.\nSmall lakes of liquid \"shadow\" flow across the surface of Deposition Shadow.\nBy Anonymous");
        add("book.pasterdream.content.暗影地牢入口", "This is no place for you. Go back to wherever you came from.\nBy Calais");
        add("book.pasterdream.content.欺诈", "It did not trust me. It kept my shadow to restrain me — like a human, my shadow learned how I think, how I fight, gradually drawing closer to me. But it answers to the shadow, always following me, watching whether I've fulfilled the terms of the bargain.\nAfter reading Aaroncos's remaining manuscripts and the Book of Shadows, I tried to establish a new way of communicating with the shadow — one-sided.\nI succeeded! I deceived my shadow, and the shadow itself. Before fleeing, I laughed wildly — I swaggered out of this place right in front of the shadow.\nBy Calais");
        add("book.pasterdream.content.交易", "I walked deeper, my steps growing lighter, until I was drowned among this black water. Countless whispers surged in like seawater; the searing pain in my skull nearly knocked me out. The whispers gradually converged, until only one voice remained.\n\"Give me your power; in return, I can do anything for you — but not as your slave\"\nAt that moment, the whispers scattered into a hubbub, as if debating fiercely, then gathered again.\n\"The door\"\nBefore I could even react to what that meant, I had already been kicked out of the Land of Darkness.\nBy Calais");
        add("book.pasterdream.content.破碎", "\"Shut up!! Everything I am now is because of him. How dare you still ask me to save him!\"\n\"Look at this face of mine — is it even human anymore?! What difference is there between me and those monsters outside? And do you know? No, you don't. It hurts. It really, truly hurts. I should throw you into the fire so you can feel it too!! I haven't had a single peaceful night's sleep in ten whole days.\"\n\"As for Yinuo, why should I save her? I've been a fool just like...\"\n\"No, no! No!! It's all of you — you all deserve to die!!\"\n\"If it weren't for you, none of this would have happened. You — since you're so determined, then stay here forever. As for Aaroncos, I will break the seal myself and grind his bones to dust!\"\nBy Calais");
        add("book.pasterdream.content.黑暗之地", "No no no, this place... I can hardly see anything here. I feel like black mist is right over my eyes!\nI could only call out like a headless fly: \"Yelan! Where are you? Can you hear me?\"\nThis goes back to a few days ago, when we were exploring that infested church in the pink dream. In the floating scroll there, I found a note left by a predecessor named Calais; the coordinates at its end pointed to the upper layers of the Nether. I'm sure you who read this book have also experienced that unsettling whisper. Back then, Yelan led me through the portal to find that damned lantern.\nYelan took the equipment and prepared to climb: \"I'll take the gear and check on that Twilight Lantern first. Wait here for me; if all's well, I'll call you over.\"\nI replied \"Mm.\" and waited below for her news.\nThen, suddenly — probably right when Yelan touched the lantern — I felt a flood of black mist surging over me, and then I couldn't see anything...\nWhen the mist cleared, I hurried up to find her, but she was no longer near the lantern.\nWhile I was investigating around the Twilight Lantern, suddenly my mind was flooded with that thing's whispers, and my body was completely out of my control. My last memory was my hand pressed hard against that icy cold lampshade. After that... I remember nothing.\nCalais was right — it really can beguile people...\nBut judging by my current state, I must have touched the lantern, fallen unconscious, and happened to collapse onto that black bed — and now I've ended up like this.\n\"Hey! Can you hear me?! Hey! Is anyone there——!\"\nJust as I was calling out in all directions, a hand suddenly reached over and covered my mouth, so I could only go like: \"You... aaaaah... wha... mmm! (Let go of me!)\" — making some garbled sounds.\nThen Yelan's familiar, deliberately lowered voice reached my ears: \"Shh! Don't speak! It's me.\"\nSeeing that I'd quieted down, she let go of the hand covering my mouth — I must say, she's really strong; she pressed so hard it hurt like hell...\nI glared at her and let out the complaint her hand had been muffling: \"What are you doing! That hurt — no sense of strength at all, I felt like I'd been pinched by pliers!\"\nYelan pointed... well, outside, and said to me: \"Haven't you seen that bunch of monsters out there? If you want to live, be careful.\"\nI followed her finger and saw only a wall blocking my eyes from what she wanted me to see: \"I can't see anything anyway... where is this?\"\nYelan spread her hands: \"This is a shelter I built. Well, actually, I borrowed someone's grave.\"\nHiss... borrowed someone's grave... A chill ran down my spine. I was just about to ask her about that when, the moment I said the first word, she immediately went \"Shh!\" signaling me to be quiet.\nFine — it seems I nearly caused trouble just now. Sigh, Miss Yelan, Miss Yelan — so you're the kind of person who uses others' graves as shelters. Tsk, how wicked. (That last line was a joke~)\nAfter sitting down, Yelan stared at me: \"By the way, you actually followed me. I didn't even signal you.\"\nI scratched my head: \"I was just worried about you~ The black mist suddenly rose, and I feared something had happened to you, so I came right away.\"\nYelan looked at me with some surprise: \"Then? About 3 days have passed.\"\nHuh? Three... three days? So much time had passed? Does time here flow differently from the Nether?\nThen Yelan told me the stories of this place... including this \"grave\".\nHer account resolved many of my confusions about this world; I could only sigh: \"I see...\"\nBut on reflection... I decided not to record these things for now.\nThere are many vague things... I need to verify them carefully.\nBy QYM");
        add("book.pasterdream.content.阴影小木屋", "After a long period of exploration and comparison, I've made a rough record of this dark world's environments.\nMost regions of this world are extremely dangerous.\nIn the mountains covered by thick shadows, the flowing and condensing shadows constantly spawn horrific monsters that make one lose their wits at a mere glance.\nThe plains piled with bones and ruined walls — endless Shadow Ghosts wail mournfully; one simply cannot stay long.\nOnly here — this \"forest\" full of fungus \"trees\" — is relatively safe.\nThe \"leaves\" of the fungi bear several glowing bodies; in this pitch-black world, such light seems able to dispel the shadows and suppress the spawning of Shadow Creatures.\nThe natives here are a gentle kind of beetle; as long as you don't attack them, you'll be safe.\nWhile strolling through this forest, I happened upon a house.\nInterestingly, the walls of this cabin seem to be made from the stipes of the fungus trees.\nAfter peeling away the layer of shadow clinging to a stipe's surface, I found its appearance identical to the cabin's walls — a material similar to... stripped logs?\nThis house seems to have been abandoned for a long time; the only traces of human life are a few scattered carpets. Even the native beetles have made their home inside, and I had to drive them away to examine the interior carefully.\nWhile inspecting the floor, I found several patches of unnatural shadow attached to it.\nI stood at a distance and lightly pressed one patch with my foot.\nFrom beneath the shadow, a hand made of shadow shot out, grabbed my foot, and tried to pull me into the ground. I struggled desperately and finally pulled my foot free from the Shadow Hand — but when its palm touched my ankle, I felt as if a layer of my sanity had been peeled away.\nWhile trying to sweep away another patch of shadow, it changed shape before fading, becoming the hand-shaped monster I'd seen in the shadow-covered mountains. It took some effort to cut it to pieces.\nI have a feeling I'll encounter this kind of \"trap\" again elsewhere.\nBy Jixing");
        add("book.pasterdream.content.阴影地下工作室", "Though this forest is relatively safe, to completely eliminate disturbance from Shadow Creatures, I decided to build a workspace underground.\nThanks to some supplies brought from the Overworld, I could at least build a small room for showering in the bedroom — after swimming through great tracts of shadow, one always wants a proper rinse.\nI planted most of the plants I could find across this world into flower beds. Though somewhat odd, tending these plants always relaxes me a little.\nAmong these gray-black plants, one I call \"Shadow Mushroom\" is especially special — unlike other plants, this mushroom seems to share properties with saplings: as long as it has enough growing space, it can grow into the fungus trees seen everywhere in the forest. It seems this forest's formation is closely tied to this mushroom.\nWhat's remarkable is that this mushroom must have ample space to grow.\nEarlier, when I planted it in a flower bed, it suddenly grew wild, wrecking the flower bed.\nTo prevent that from happening again, I moved it out of the bed and restricted its growing space. (The fully grown fungus tree next to it, though, I kept for continued research.)\nAfter tinkering with certain materials of this world, I finally reproduced the black long bed I used to come to this world. It seems lying on it can take me back to my original world.\nBut many unknowns in this world still await exploration; until I've unraveled them all, I don't plan to return to the Overworld lightly.\nAh, it seems a beetle has crawled in. Though this beetle isn't aggressive, I still don't like being disturbed — time to go shoo it away.\nBy Jixing");
        add("book.pasterdream.content.-被阴影浸染的字迹潦草的笔记-", "Unbelievable — I actually escaped from the hands of that dreadful creature.\nThey were a pair of huge black hands with a white eye in each palm. Just locking eyes with them made my whole body tremble; I couldn't muster the slightest will to fight.\nEven so, I forced up my courage to face them, only to find their terrible power far beyond my imagination.\nThe slightest attack against them provoked a fierce counterattack.\nIn the heat of battle I was so panicked that I couldn't even tell which hand I was attacking.\nYet I clearly remember: attacking one hand made it sprout a spike and flail it wildly.\nWhile attacking the other hand made it release a spire that seemed to hold immense energy — apparently about to explode violently.\nUpon seeing such dreadful counterattacks, I fled in panic at once — fleeing until I forgot how I even escaped.\nTo those who come later, I hope my disgraceful experience can contribute something to your exploration.\nUnless you possess power enough to tread this ghastly, dreadful world without any threat, please never approach the place of that \"eye\".\n-Author's name illegible-");
        add("book.pasterdream.content.关于黑暗之手的随笔", "After roughly finishing my exploration of all this world's biomes, I gained a considerable understanding of nearly all its structures...\n...except for that \"eye\" wrapped in four \"fingers\"...\nThe glowing portal at its center seems to lead to a simple but unsafe space.\nTo be safe, I managed to send a sturdy machine equipped with an image-transmission device into the portal to scout in my stead.\nAfter passing through the portal, it slowly landed at the center of an \"arena\".\nThe image began to blur; the ground shook violently, and then two black giant hands emerged from thin air.\nUpon spotting this \"foreign object\" I'd thrown into the portal, the two hands immediately launched fierce attacks at it from front and back.\nIn the view, one hand suddenly charged over, flipping the machine over; then amid darkness and a gale, the machine's vision went dark and lost contact with me.\nNo good — too many variables this way; with only this much information, there's no chance of victory.\nEven so, I'll leave this note behind for now. Though it holds almost no valuable information, it should still be of some use to those who come later.\nBy Jixing");
        add("book.pasterdream.content.侵染教堂-黑面", "I'm grateful to have made it back alive, leaving that place without light. But soon I discovered that the cold, grim aura still hadn't vanished — until a rift appeared in the sky, from which a black, viscous liquid gradually seeped out.\nIt... followed me...\nThe liquid dripped to the ground, then began polluting its surroundings, gradually eroding the church. While using spring water to slow its spread, I racked my brain for the knowledge in that book. I wasn't sure the book's method would work, but for now I had to gamble on it. In the church I found the candles and thread I needed — but one key item was still missing: a container.\nI gave up on the several eroded chests in the church, and prayed the lanterns with big holes would do. As the lantern was thrown into the middle of the runes, it gradually began to rise, and the black liquid was drawn by a tremendous pull, continuously merging into the lantern — until the church stopped being infested. Suddenly the wick lit, emitting an eerie white glow.\nI hurriedly caught the lantern as it fell from the air; a bone-chilling cold came from my arms, and whispers swirled around me, seeping into my mind.\nBy Calais");
        add("book.pasterdream.content.侵染教堂-亮面", "It's actually a church...\nYinuo and I didn't rush in. Though the previous buildings posed no danger, to be cautious we circled the church several times before deciding to enter.\n\"Milady, this church is a bit strange — it doesn't match what the church requires, and the interior decor differs greatly too.\"\nI kicked the lectern. There were no chests under this church's lectern. Weekly prayer days lasted most of the day, and the chest under the lectern would hold some food. Besides that, it was too small — smaller even than the village churches in the territory — and inside there were hardly any prayer-related objects.\nAs I was about to leave, Yinuo noticed something unusual: a white-gold chest had appeared under the lectern.\nI was certain there had been nothing under the lectern before, but this chest's appearance made me a bit tense. As I hesitated over whether to open it, the familiar sound of wind chimes rang out again — coming from that chest...\nBy Calais");
        add("book.pasterdream.content.暮影之笼", "Though I hid it here, I still fear it may be discovered, so I leave this letter to warn later travelers: do not approach this place lightly. What lies within cannot be opposed by the power of this world; you will be corrupted and beguiled, and through you calamity will be unleashed, dragging the whole world into darkness.\nOf course, I'm not worried either — if you possess power surpassing mine, you may explore what I sealed away, even accomplish what I never touched.\nBy Calais");
        add("book.pasterdream.content.与黑色双手的决战和败北", "I write this note to warn those travelers who would challenge it: \"It\" is far more powerful than you can imagine.\nAs for what lies beyond that glowing portal, the notes left by the other Dreamseekers exploring the Lamp Shadow and by my friend gave me the answer: beyond the door is a small sealed world, home to a dreadful Shadow Creature shaped like a pair of hands.\nTo defeat it, I forged armor and weapons from the toughest metal obtainable in the pink dream, and after making every preparation I could think of, I leapt into the portal.\nYet even with all my preparations, the battle was still exceedingly grueling.\nEndless shadow monsters surging from nowhere, and the black hands' ferocious assaults — they ceaselessly ravaged my mind, will, and stamina.\nEven so, I attacked it with all I had, and in return received even fiercer counterattacks — but I still believed I had dealt it effective damage.\nJust as I thought victory might be possible at this rate, something dreadful happened.\nIn an instant, my vision plunged into darkness. In the pitch black, it seemed endless Shadow Creatures writhed forth, and my attacks couldn't even pierce the thick layer of shadow around those hands.\nSurrounded by monsters, potions exhausted, badly wounded, I prayed desperately in my mind that this was only a dream, and grabbed the Pale Boneneedle to stab hard into my own arm.\nAfter a sharp sting, my vision was seized by bright light. In the blink of an eye, I stood beside my familiar bed. But my body drenched in cold sweat, my armor riddled with cracks, and my empty potion bottles told me the ordeal just now was no simple dream.\nIndeed, to defeat this dreadful creature, one needs weapons that can suppress the shadow, or merge into it and destroy it from within.\nSo I must have missed some key point after all. Perhaps it would be better to wait for other aid to come and face it together.\nUntil then, I must find a way to obtain a more powerful weapon...\nBy Qianye");
        add("book.pasterdream.content.暗影图书馆", "I know you too wonder why this place exists. I gathered the remnants from the ruins and stored them here; here you can learn my story and the history of earlier times.\nIf you only wish to understand the shadow — unfortunately, such materials were destroyed or hidden. It is dangerous; do not touch it under any circumstances.\nOf course, I keep insurance. (Smiley face)\nBy Calais");
        add("book.pasterdream.content.破风的骑士", "The crumbling ruins of Ancient Greek-style architecture form a circular temple, at whose center is enshrined an unremarkable altar.\nIs it for praying for rain? Or hoping to divine the wind's direction? Or enshrining one's patron god?\nI approached the half-brick altar at the center and crouched down, finding a black hole in the middle with a rolled-up strip of paper standing inside it.\nOn it were drawn some scrawled diagrams and a numbered sequence: a blue crystal, and 3 suits of armor seemingly made of metal.\nAnd at the very bottom of the paper was written:\n\"The Wind-Breaking Knight\" will drive away everything beyond what it protects...\nBy QYM");
        add("book.pasterdream.content.清晨的新风", "This is the beginning of a new day, and the arrival of a new wind direction.\nAccompanied by the sound of wind chimes, falling feathers, and the rising sun from the east.\nThe wind is this place's gift; following its direction will aid our exploration, while going against it may leave us unable to move an inch.\nThe wind not only guides the direction of our journey, but is also a special key.\nThe wind only blows anew when a new day comes; it cannot be predicted by any means.\nIf you miss the guidance of the morning wind, or cannot feel the wind direction physically outside this dream, a Wind Vane can cross the line between reality and dream to tell you the current wind direction.\nAnd some treasures scattered here can change the wind's influence on us.\nThere are still many secrets of the wind... perhaps one day, the wind will reveal them to us.\nBy QYM");
        add("book.pasterdream.content.魔法使的记录-其一", "Pink, drifting petals, clouds, and all manner of buildings that exist only in fantasy — everything in this world is like the embodiment of a maiden's every dream.\nThat being so, this world truly is a dream — peaceful, cozy, simply the finest sweet dream...\nHowever, even if this is a dream, my habits still led me to ask myself a few questions: Where did such a beautiful world come from? Who built those mysterious buildings? And... where does the wondrous feeling I sense come from?\nIf I figure these out, perhaps I can grasp more secrets and learn more magic.\nWhat a marvelous world — so alluring. Every riddle of this world tempts me to seek the truth.\nBy Lingran");
        add("book.pasterdream.content.魔法使的记录-其二", "Wind, clouds, sky islands. This world is dominated by the wind at all times — even the clouds can bear one's weight. Every sunrise, the wind direction here changes anew...\nHere, one must obey the wind's will: following it makes our journey smooth, while opposing it makes progress difficult.\nTo explore this place, I built a hot-air balloon and used flame magic to provide lift. As for propulsion... I'll leave that to the wind.\nSince it was a long expedition, I moved my living space onto the balloon and reinforced it well.\nBut as they say, plans never survive contact with reality: once, when the balloon passed through those rings floating in the sky, it got stuck. So I broke the cloud rim of the ring — and the result was that the balloon suddenly lunged forward, almost flinging me off.\nFrom this, it seems this thing can accelerate one through objects... hmm... an Elytra should allow more agile exploration. Though not very safe, of course.\nI abandoned my balloon there and continued the journey with an Elytra and fireworks.\nAs for the magic gems left in the chest and such... I really can't carry them all. Might as well leave them; it's not like they're particularly valuable.\nBy Lingran");
        add("book.pasterdream.content.空岛的圣诞树", "Relying on an Elytra and the Break Wind Curtains found all over this place, I reached a sky island full of Christmas atmosphere.\nEverything here stands upon the clouds, like a heavenly kingdom from myth — even eternal time has left no mark here, leaving only boundless winter.\nThis island may be a natural landscape of this world, or perhaps built by someone who once celebrated the holiday here.\nBesides us, others not belonging to this dream have come here too. Some pay homage; others simply enjoy the festive atmosphere.\nIn our civilization, the Christmas tree symbolizes not only good fortune and peace, but also the herald of spring's arrival.\nI wonder how people from other worlds would view this tree. Perhaps they'd find it festive too.\nI walked a full circle around the Christmas tree and found a snowflake-shaped hairpin in the chest.\nHolding it, I felt a strange sensation — like one person making a vow to another, binding each other.\nIs it a vow made in alliance, or a promise between lovers to grow old together? I cannot know...\nI don't want to dwell on such trifles; I'll just leave it here. Perhaps a later Dreamseeker will need it.\n...Actually, it's simply because I'm not used to wearing too many hairpins. Leaving it for later comers is secondary.\nBy Lingran");
        add("book.pasterdream.染梦游记 其一_第1页", "Dyedream Travelogue I\n\nA pink crystal sprout grows underground in warm regions\n\nThe slime-like creatures have natural protective coloring; perhaps you can find them by sound\n\nThe oceans here also hide treasures\n\nSome chests are hidden away; maybe it's the same here?");
        add("book.pasterdream.染梦游记 其一_第2页", "Strange flower beds offer unique flowers to those who can solve their puzzles\n\nLuck is the key to finding treasures here\n\nThe caves underground may hold crystals that increase your vitality\n\nThere's a special kind of spring here\n\nThe Worldtree's interior also hides treasure... and...");
        add("book.pasterdream.染梦游记 其一_第3页", "Everything I have seen feels strangely familiar... as if I've experienced... all of this before\n\nBy QYM");
        add("book.pasterdream.染梦游记 其二_第1页", "Dyedream Travelogue II\n\nAn edible ore with a sweet taste can be found in the shallow underground\n\nRare titanium metal can also be found, though its color blends with the environment, making it hard to spot\n\nA fruit grows on the Dyedream leaves; you can turn it into a cake\n\nNative crops need a special mud fertilizer to ripen");
        add("book.pasterdream.染梦游记 其二_第2页", "Grinding Dyedream Dust together with bone meal can produce a special dye\n\nThe pink quartz minerals growing underground are excellent building materials!\n\nAn underground research institute houses a device that can accumulate Dyedream Dust\n\nBy QYM");
        add("book.pasterdream.染梦游记 其三_第1页", "Dyedream Travelogue III\n\nExploring here feels relaxing; even doing nothing lifts my mood\n\nAfter so long exploring, I've discovered four biomes in total — two temperate, two cold\n\nCoral actually grows beneath the frozen ocean\n\n");
        add("book.pasterdream.染梦游记 其三_第2页", "It seems a train passes by from time to time; I wonder if it's an illusion\n\nI also found some nice records in the chests of some ruins\n\nI found that the more a Melt Dream Crystal Chest vibrates, the better the treasure inside\n\nSome churches stand out — half of the building looks like something has invaded it");
        add("book.pasterdream.染梦教堂 其一_第1页", "Dyedream Church I\nA record for myself and for those who come later\n\nIn this so-called \"world\", I actually found a huge building floating in the sky. I'm sure I wasn't seeing things! If you who come later can also see this book...\n\nI instinctively believed I was in a dream, yet all of this felt so real.\n\nWhen I climbed onto this great building, th");
        add("book.pasterdream.染梦教堂 其一_第2页", "It looked like a church? But there was no one inside (though, who would live in the sky?)\n\nThe candles were still burning, as if they would never go out. Sunlight streamed through the glass opposite the entrance, filling everything inside.\n\nUpon the altar was a beautiful floating crystal, radiating light in all directions... (I stared at it for a long time)");
        add("book.pasterdream.染梦教堂 其一_第3页", "I reached my hand toward the crystal, and it suddenly seemed to sense my presence; it fell to the ground and closed tight. (Of course I took such a fine thing, but maybe it will regrow when you come? Perhaps...)\n\nI held the crystal in my palm, and it seemed to speak to me... heartfelt prayers from other souls.\n\nI turned to the great window at the back of the church, closed my eyes, and made my own wish...");
        add("book.pasterdream.染梦教堂 其一_第4页", "Oh right, one more thing — I'm leaving this book right here!\n\nWhy? ...Because I want my story to remain in this world forever, that's all~\n\nBy: QYM");
        add("book.pasterdream.染梦教堂 其二_第1页", "The day before yesterday, QYM suddenly told me a secret — she said she'd entered a dream-like place, and kept insisting it was real?\n\nAt first I didn't believe her, but she kept insisting I follow her to that magical place to adventure, to make a wish at that so-called church.\nI refused several times, but in the end I decided to follow her and see what her world and that wondrous church were really like.");
        add("book.pasterdream.染梦教堂 其二_第2页", "After I passed through that astonishing rift and saw the scenery before me, I even pinched my arm... could all this really be real?\n\nI followed her to the church — blue soul lanterns and towering spires, a spiky Western building. It's hard to imagine why there would be traces of humans here.\n\nI decided to climb the floating island bearing the church to find out.");
        add("book.pasterdream.染梦教堂 其二_第3页", "Inside the church floated lit candles, and glowing lanterns stood by the pews, filling the church with mystery and unreality. I'm not sure whether these mean anything, but I've decided to record them.\n\nI wandered the church for a long time, taking in the atmosphere. It was full of mystery and a wonderful aura. I can't explain why I feel this way, but I know some wondrous power dwells here.");
        add("book.pasterdream.染梦教堂 其二_第4页", "I held her hand and explored every corner of the church, when she suddenly went \"Ouch!\" — \"Why are you pulling me into a wall?!\" Then she stopped and stared at me in surprise.\n\n\"You... why are you inside this wall? Are you okay?\" What wall? I didn't understand what she meant at all.\n\n");
        add("book.pasterdream.染梦教堂 其二_第5页", "She suddenly began dragging me in circles along the wall, and then I, too, bumped into something I couldn't see — this time... she was standing inside the wall...\n\nShe then described this church to me in remarkable detail: in her description, the lectern had no lanterns, nor were there huge floor-to-ceiling windows.\n\nWe discussed it for a long time. \"Could we be seeing it differently? And not just visually?\" she said to me.");
        add("book.pasterdream.染梦教堂 其二_第6页", "And when I looked at the mysterious crystal hovering over the prayer desk beneath the great floor-to-ceiling window, I don't know why, but I felt it was the cause.\n\nQYM stroked the crystal with practiced ease, and it naturally floated along with her palm.\n\n\"QYM...\" \"Hm? What is it?\" \"Ah, nothing...\"");
        add("book.pasterdream.染梦教堂 其二_第7页", "I've decided to write down everything I experienced here into a book and leave it in the church for those who come to this place later.\n\nThat way, when my book is discovered, perhaps...\n\nBy Yelan");
        add("book.pasterdream.染梦教堂 其三_第1页", "\"Is this place... a little too wonderful? Yinuo\"\n\nShortly after entering, this thought suddenly crossed my mind. Yinuo said I was overthinking it. True enough — there are no monsters here; everything is full of life and vitality.\n\nBut when I tried divination, the three results all differed — meaning the scene I see is not the true scene.");
        add("book.pasterdream.染梦教堂 其三_第2页", "\"Where there is light, there is darkness; the stronger the light, the thicker the darkness\"\n\nAfter half a year of ceaseless exploration in the dream, I discovered this... church half-dyed in black.\n\nThis abrupt blackness appeared in a place it never should have. Suppressing my trembling body, I stepped into the church.\n\nBy Calais");
        add("book.pasterdream.染梦水晶球_第1页", "When I was little, I dreamed of living inside a glass ball — my own little world!\n\nHaving my own tiny ecosystem would be so cool, and being wrapped up in it would be even better~\n\nBut I don't really like those huge empty houses; I prefer having my own little world.");
        add("book.pasterdream.染梦水晶球_第2页", "Just lie here, cradled by clouds, gazing through the pink glass at the sun through the clouds.\n\nMm... mm~ Just like this... have a sleep...\n\nWish you sweet dreams\n\nBy QYM");
        add("book.pasterdream.祈愿树_第1页", "This is a Wishing Tree!\n\nWell... as for why I call it a Wishing Tree... I don't actually know either.\n\nJust like coming to this place, I seem to instinctively know how to name every plant and tree.\n\nI can call out their names, just by following my heart, even though there's no right answer at all.");
        add("book.pasterdream.祈愿树_第2页", "Now, besides the wishes I used to make on my birthdays... I also want to know the truth of this dream.\n\nBut it seems only this one point — the tree gives no response, and I can't feel anything either.\n\nIf you who come later have answers... please continue this note.\n\nBy QYM");
        add("book.pasterdream.温暖的“寒风”_第1页", "Cold or warm?\nThe purpose of this pretty little pavilion doesn't seem to be escaping the heat.\n\nThe temperature here is always comfortable. Calling it a frozen ocean is only because the surrounding glaciers make it look \"cold\".\n\nBecause tropical coral grows beneath those glaciers, and there are adorable dolphins.\n\nMm... perhaps this can't be explained by physics?\nOr is it some geographic wonder?");
        add("book.pasterdream.温暖的“寒风”_第2页", "These pavilions also differ in color — pink roofs in temperate regions, blue in cold ones.\n(Quite fitting for the local style~)\n\nThe undergrounds of temperate and cold regions also differ, spawning different crystal formations. Perhaps these crystals will be useful to us...\n\nBy QYM");
        add("book.pasterdream.粉顶蘑菇屋_第1页", "This is my second time here; it's been over ten days since I last came to this dream.\n\nWhen I returned to the waking world, I told her about the bizarre experience. But obviously she couldn't believe it — she even thought I'd eaten something wrong?\n\nSo I grabbed her arm and forcibly dragged her here. At first she was stunned... but her adaptability is as fast as always.");
        add("book.pasterdream.粉顶蘑菇屋_第2页", "This time we walked for a long while and found a place with a completely different biome.\n\nMushrooms, mushrooms, and more mushrooms — pink mushrooms.\n\n\"Such huge mushrooms could even serve as a house!\"\n\nThen... a giant mushroom house really appeared before us...");
        add("book.pasterdream.粉顶蘑菇屋_第3页", "It was unbelievable; we stood before that exquisite mushroom house, dumbfounded for several minutes.\n\nBedroom, kitchen, desk, storage chests — everything one could want. This absolutely cannot be nature's handiwork.\n\nThe strangest thing is that this house appeared out of thin air?");
        add("book.pasterdream.粉顶蘑菇屋_第4页", "\"Because we're dreaming, this is all normal, right? Ha...haha...\" I teased.\n\nI even found myself accepting this fact so readily... my brain was overloaded, so I simply stopped thinking about it!\n\nAfterward, we explored the surrounding ecology and spent a night in the mushroom house.\n\nAs always, I'll leave this book here.");
        add("book.pasterdream.粉顶蘑菇屋_第5页", "If you who come later find it, please don't eat the mushroom house! I'll come back to play sometime... maybe.\n\nBy: QYM");
        add("book.pasterdream.融梦涌泉井_第1页", "So you've seen this? Then let me start from the beginning.\n\nWhen I first strolled here, the vegetation here grew differently from elsewhere.\n\nIn a relatively small area there are many different kinds of vegetation, and the density is quite high.\n\nCompared to other places, that's indeed suspicious, so I bent down to study the soil here.");
        add("book.pasterdream.融梦涌泉井_第2页", "From the surface, it looks no different, but the deeper you dig, you find that scooping up a handful of dirt lets a few tiny glowing specks trickle through your fingers.\n\nNaturally, I went to rally the troops. I went home, called on Yelan, and brought two handy shovels and her treasured Titanium pickaxe.\n\nAs we dug deeper, we gradually found many tiny glowing specks in the soil.");
        add("book.pasterdream.融梦涌泉井_第3页", "We set up ladders and climbed down; a glowing spring was gushing forth in a lush cave. Perhaps this glowing spring is the sun of the underground vegetation.\n\nBut by science, nothing with infinite energy can exist, so we built this \"well\" with the materials at hand. I brought a bottle of the spring water home; I hope my research goes well.\n\n");
        add("book.pasterdream.融梦涌泉井_第4页", "As for the rest, I'll leave it to you who come later.\n\n(Don't forget the well digger when you draw water — remember to thank me~ Hehe)\n\nBy QYM");
        add("book.pasterdream.浮空岛日记_第1页", "How do you suppose these buildings and islands floating in the sky came to be?\n\nNature's handiwork? Or the work of those who came here before us...\n\nThen stones and dirt shouldn't be able to fly either — how could nature create traces of human making, and how could humans construct all this beyond reality?\n\n");
        add("book.pasterdream.浮空岛日记_第2页", "Ugh, thinking hard about these things makes my worldview collapse.\n\nBut there's no need to dwell on it~ Maybe, as my intuition tells me, all of this is just a dream.\n\nImagination is boundless — I could even make this island speak! Don't you think~");
        add("book.pasterdream.浮空岛日记_第3页", "But one day, I will come to understand all of this...\n\nMay this journey become a memory I can never forget.\n\nBy QYM");
        add("book.pasterdream.落叶归根 裂荚归冠_第1页", "Vigorous giant tree, your branches and leaves are your children; when they wither, they fall beside your roots\n\nOther plants cast off their pods at birth, abandoning the last shell their mother left them\n\nBut you, with your topmost branches, hoist the pod high into the sky\n\nWith roots and leaves you nourish it, letting it bask in the highest light — the light crowning the top of this world");
        add("book.pasterdream.落叶归根 裂荚归冠_第2页", "Even after the pod has long fulfilled its purpose, it still uses these nutrients to build its own dream\n\nAnd so I offer my wish to you, as a first-meeting gift\n\n\nBy QYM");
        add("book.pasterdream.梦境漂泊_第1页", "Drifting Through Dreams\n\nIn the ocean of dreams, I drift, unmoored\n\nLike a lonely traveler, seeking unknown wonders\n\nThe starry sky keeps me company; the earth is my bed\n\nIn this sleeping realm, I dance with dreams\n\nMist beneath my feet, the unknown ahead\n\n");
        add("book.pasterdream.梦境漂泊_第2页", "With all my heart, I feel the rhythm of every journey\n\nThere is song in the wind, stories in the rain\n\nEvery moment is a wonder of the dream\n\nI am a drifting traveler, fearless and unafraid\n\nIn the depths of dreams, I seek the truth of life");
        add("book.pasterdream.梦境漂泊_第3页", "Only to\n\nOn this endless journey, become my own legend.\n\n\nBy QYM");
        add("book.pasterdream.气泡生态球_第1页", "Just as I was rowing my wooden boat across the ocean, searching for the ruins floating in the sky, I looked around during a break and happened upon this wondrous sphere.\nThis sphere floated in the icy seawater, fish faintly visible through its transparent membrane. I dove in, carefully reached out to touch the membrane, and — after feeling a slight resistance — passed right through it.\nIncredibly, the inside of the sphere was quite warm, a stark contrast to the freezing ocean water that had just soaked me to the bone");
        add("book.pasterdream.气泡生态球_第2页", "forming a stark contrast. I crouched and reached through the thick cloud blocks to feel around — sure enough, the water beneath was warm too. The tropical fish here were no specimens, and the vivid colors I'd seen from the boat were no illusion born of being frozen senseless.\nCarefully examining the interior, I couldn't help recalling the ecospheres I'd seen before. Was this marvelous bubble sphere built by beings beyond human intelligence, or naturally formed by this unbelievable world?\nI cannot know.");
        add("book.pasterdream.气泡生态球_第3页", "But at least the small fish drifting slowly here bear me no hostility, just like the other creatures of this world. I could sit here and rest a while before swimming back to my boat.\nWith that thought, I casually poked the bubble wall beside me with a wooden stick — and the surface erupted into violent ripples, nearly bursting, making my heart skip a beat. Indeed, I'd best be more careful next time. Such fragile bubbles can probably only exist in calm frozen waters; the slightest poke might destroy them entirely.\nOn the blank title of my note, I wrote");
        add("book.pasterdream.气泡生态球_第4页", "the name \"The Bubble Biome Sphere\". After all, it is as beautiful and fragile as a small ecosphere; best to disturb it as little as possible.");
        add("book.pasterdream.染梦实验室_第1页", "A dilapidated building — I've found traces of predecessors in this dream.\n\nI'm not the only one who found this strange, pink-filled place, but when I called out loudly, no one answered. The people have already left.\n\nDim lamplight enveloped the interior of the ruin, at the center of which sat a trapezoidal unknown device.");
        add("book.pasterdream.染梦实验室_第2页", "I'm convinced this place is the laboratory of a predecessor who arrived here earlier, and that the device at its center is their final labor of love.\n\nRegrettably, I couldn't discover why the predecessor left in such haste.\n\nNow, I should carry on their research with this damaged device.\n\nBy: Huixing");
        add("book.pasterdream.来往于梦_第1页", "To those who come later:\n\nThis writing records what I have seen and heard here, along with some speculations. I don't know what kind of world this truly is.\nBut (crossed-out text) \"miracle\" — that's the only word I can use to describe the world before my eyes.\n\nPink everywhere, an eternally bright sky, and darkness that breeds no loathsome evil — like a dream. No, perhaps it IS a dream");
        add("book.pasterdream.来往于梦_第2页", "Though raised on materialist education, facing a scene completely inexplicable by existing knowledge, I can't help but ask:\n\nCould there really be some kind of deity in this world? (And would such a deity be the idealist \"god\", or a higher \"existence\"?)\n\nStill, there are no small number of doubts here; everything is relative.");
        add("book.pasterdream.来往于梦_第3页", "Since such a beautiful world exists, is there a place completely opposite to it? Moreover, this world has a strange sense of unreality everywhere — everything is so real, yet every place feels alienating (somewhat like a lucid dream?)\n\nWho created this miracle, and who sustains it (oversees it?)\n\n§m>Large tracts of crossed-out text<");
        add("book.pasterdream.来往于梦_第4页", "Perhaps someone once stayed here (settled?), given the presence of smokers, flower pots, and bookshelves — objects full of the flavor of life.\n\nBut the owner has likely been gone a long time (strangely, most items look brand new, and the flowers on the windowsill are still alive).\n\nAs for this world, for now let me call it a \"dream\"");
        add("book.pasterdream.来往于梦_第5页", "More conclusions await further exploration to verify; perhaps I need a more stable way to travel between reality and this \"dream\".\n\nBy Liuhua");
        add("book.pasterdream.染梦世界树_第1页", "While gazing at the scenery from afar, I spotted this towering giant tree at the edge of my vision. Standing at its base and looking up, the trunk soared into the clouds, its canopy barely visible.\n\nDigging the soil around the roots, I found its roots don't extend very far — hard to explain its extraordinary height\n\nThe winding trunk formed a natural staircase, though some parts still required free-climbing. When I reached the top of the branches, I could see a small hollow inside.");
        add("book.pasterdream.染梦世界树_第2页", "A glowing white spring flowed from the trunk's side, anomalous in every way — though compared to this world itself, this sight was hardly enough to astonish me.\n\nBack under the tree, I began to ponder what enabled this tree to form and grow normally. On this, I made a conjecture:\n\nThis world belongs to some kind of dream, and the dream energy in its atmosphere is unevenly distributed.");
        add("book.pasterdream.染梦世界树_第3页", "Just as atmospheric phenomena cause weather changes, this energy dissolved in the dream's air — Melt Dream Energy — should also be unevenly distributed.\n\nIn regions where Melt Dream Energy settles more, the energy condenses into physical forms, creating continents, sky islands, trees, and everything else in this world. And where it gathers in large amounts within a small area, the result is a Melt Dream Crystal Chest — which also explains why energy escapes when you open one.\n");
        add("book.pasterdream.染梦世界树_第4页", "Extrapolating from this theory, at the center of this dream world — where Melt Dream Energy is most abundant — a colossal structure should form; and the rich energy would manifest as countless Melt Dream Crystal Chests accumulated within it.\n\nAt that thought, I turned to look back toward the giant tree. It may well be the Worldtree of this dream world — a place of concentrated Melt Dream Energy, a dreamland holding countless Melt Dream Crystal Chests.");
        add("book.pasterdream.染梦世界树_第5页", "I ought to climb that tree again and explore its inner structure. My earlier fruitless search must mean I missed something...\n\n\nBy Jixing");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第1页", "Daedalus' Wings and the Floating Island\n\nShortly after I left that giant tree in disappointment, Qianye caught up with me and interrupted my plan to explore anew\n\n\"See those islands floating in midair? I want to go up and see if there's any treasure there.\" I suggested to Qianye\n\nUnexpectedly, Qianye doused me with cold water: \"I think you've lost your mind. We can't fly — how would we get up there?\"");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第2页", "\"About that... I have a bold idea...\"\n\nUnder Qianye's incredulous gaze, I took out the feathers dropped by those pink chickens I'd picked up along the way. Then I melted down the candles I'd found into wax and stuck the feathers together with it, working hard to craft two pairs of wings.\"\n\n\"So you want to be Icarus.\"");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第3页", "\"No, I think I'll be Daedalus. After all, the sun here won't melt this wax. And how would we know without trying? After all...\"\n\nThings went surprisingly smoothly — though by all logic, humans can't fly with such wings; yet somehow, the wind here seemed to carry the wings, letting us fly with no effort. We easily reached the floating island I'd previously only been able to gaze up at.");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第4页", "After landing on the island, Qianye dashed straight into that little house. I followed right behind, found a spot to sit down, and chatted with her.\n\n\"Come to think of it, this world is way beyond common sense.\" Qianye took off the wings and started checking whether they'd fallen apart.\n\n\"That's why I said this world must be some kind of dream or illusion\"");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第5页", "\"After all, I can't understand at all how these islands float in the air unharmed, and stay perfectly still when we step on them.\"\n\n\"This house too — though it obviously looks man-made, there are no signs of human habitation at all. Also, I still can't understand how this thing works.\" Qianye shook the wings in her hand and said.\n\n\"Don't be so serious — anything can happen in a dream.\"");
        add("book.pasterdream.代达罗斯之翼与浮空岛_第6页", "By Jixing");
        add("book.pasterdream.探求秘辛_第1页", "In order to gather some necessary resources, I found a desert after a long journey.\nSince the resources I sought were quite rare, I might have to stay for a while; so I managed to find a village on the desert's edge and built this little hut to live in.\nSetting out at sunrise each day and returning to this temporary home before sunset; chatting with the villagers at night or when sandstorms kept me indoors — this was my daily life in the desert.");
        add("book.pasterdream.探求秘辛_第2页", "Half a year passed in the blink of an eye. My daytime explorations made no progress, but my bonds with the villagers grew warmer by the day.\nThe adults were endlessly grateful that I protected them from monsters at night, while the children reveled in the adventure stories I shared from my travels — gradually, the villagers began to reveal \"secrets\" never told to other travelers:\n\"Our village blacksmith almost never leaves his home, so you've probably hardly seen him. They say he was once a");
        add("book.pasterdream.探求秘辛_第3页", "royal craftsman of some kingdom, whose family forged all manner of elite weapons for the royal family; but after the kingdom fell, his family declined, and finally wandered here to settle. He still doesn't seem to accept his situation, and built his workshop a bit far from the village. We don't have much contact with him either, only work-related dealings... but if it's you, you should be able to get along with him...\"\nThe villagers seemed to want me to talk some sense into the reclusive, fallen forging aristocrat (though I suspect they just hope");
        add("book.pasterdream.探求秘辛_第4页", "that once I get friendly with him, they can get their tools repaired at a cheaper price). Bearing my aged vintage brew, I visited the blacksmith's workshop.\n...\nThough there were many twists and turns along the way, we eventually became close friends. During a drink together, I told the elderly smith that I hoped his family's exquisite forging skills would be passed on; though I'd learned much of his technique through our time together, I could never forge equipment of such superior capability as he did.");
        add("book.pasterdream.探求秘辛_第5页", "After a long silence, he took out paper and a pen, drew me a blueprint, and told me: only by strictly following his workshop's layout could one guide and gather some... substance? from the atmosphere to its fullest, thereby forging extraordinary and novel tools. Moved by his generosity and trust, I left behind almost all my valuables as thanks, and departed with this blueprint.\nBefore I knew it, I'd stayed in this desert for far too long...");
        add("book.pasterdream.探求秘辛_第6页", "Time to set out on a new journey — when I next stop somewhere, I'll try building a workshop according to this blueprint.");
        add("book.pasterdream.研究笔记-黑金属_第1页", "To trace the origin of this research, I must go back to some strange metal I found in this pitch-dark dream.\nIt appears in those hanging lanterns, ruins, and some pottery jars and treasure boxes.\n\nIts texture looks like iron, but its rust isn't a brown peeling layer — rather, many small black holes.\nBut smelting it in an ordinary furnace had no effect at all, so I simply threw it into lava — which, unsurprisingly, vaporized it directly.\n\n");
        add("book.pasterdream.研究笔记-黑金属_第2页", "To study this metal, Yelan and I found a run-down trapezoidal building nearby.\n\nBut by a stroke of luck, some dripping fluid shadow from the second floor fell into the jar holding this metal — and the shadow, as if conscious, filled the rusted holes by itself.\n\n\"This isn't enough,\" \"it seems this metal may just be a carrier; what's truly missing are those shadows\"");
        add("book.pasterdream.研究笔记-黑金属_第3页", "Through continuous research, we arrived at: \"high heat, flowing shadow, and the bodies of those shadow monsters\".\n\nWe woke up from here, brought some materials and equipment, and once again lay down on the bed under the Lamp Shadow...\n\nAmid the roar of the machine — fusing, melting, condensing... at last, a piece of black metal fell to the ground with a clang...");
        add("book.pasterdream.灯影游记 其二_第1页", "I'm curious how these fungi manage to grow here?\n\nThere's no light in this sky, no familiar sun, no reliable source of energy.\n\nBut these fungi drive their roots into the black stone, growing into mushroom trees taller than a person, and even bearing glowing fruit.\n\n\n\n");
        add("book.pasterdream.灯影游记 其二_第2页", "They also nurture some possibly-local creatures? These beetles feed on the fungal strands here, living here in droves.\n\nFacing the darkness, they've grown white eyes — perhaps that's how they can see in the dark.\n\nThese lifeforms together form a so-called \"ecosystem\"... which simply cannot be explained by modern science.");
        add("book.pasterdream.灯影游记 其二_第3页", "But then, from that pink-stained world to this pitch-black place crawling with monsters, it long ago stopped being explainable by science — it's entirely an illusory product of subjective imagination.\n\nSigh, I'm not a scientist anyway. But still... do you think these mushrooms... might taste good?\n\nI think I should research some recipes (and find a test subject!)");
        add("book.pasterdream.黑暗之地_第1页", "No no no, this place... I can hardly see anything here. I feel like black mist is right over my eyes!\n\n\"Yelan! Where are you? Can you hear me?\"\n\nThis goes back to a few days ago, when she was collecting herbs in that pink dream and saw a church half-invaded by blackness...\nI'm sure you who read this book have experienced it too; she also led me here.");
        add("book.pasterdream.黑暗之地_第2页", "\"I'll take the gear and check on that ghost-shadow lantern first. Wait here for me; if all's well, I'll call you over.\" \"Mm\"\n\nThen, the moment she touched the shadow lantern, I felt a flood of black mist surging over me, and then I couldn't see anything...\n\nWhen the mist cleared... she was no longer near the lantern.");
        add("book.pasterdream.黑暗之地_第3页", "So I must have run over and touched the lantern, and ended up like this.\n\n\"Hey! Can you hear me?! You... aaaaah... wha... mmm! (Let go of me!)\" \"Shh! Don't speak!\"\n\n\"It's me (very quietly)\" \"What are you doing! That hurt — I feel like I fell to the ground!\"");
        add("book.pasterdream.黑暗之地_第4页", "\"Haven't you seen that bunch of monsters out there? If you want to live, be careful.\" \"I can't see anything anyway (muttering)\"\n\n\"This is a shelter I built. Well, actually, I borrowed someone's grave.\" \"Wh-?!...\" \"Shh!\" \"Mm...\"\n\n\"By the way, you actually followed me. I didn't even signal you.\" \"I was just worried, so I followed right along\"");
        add("book.pasterdream.黑暗之地_第5页", "\"Followed? It's been about 3 days.\" \"Huh?\"\n\nThen... she told me the stories of this place... including this \"grave\"\n\n\"I see...\" But on reflection... I decided not to record these things for now.\n\nThere are many vague things... I need to verify them carefully.");
        add("book.pasterdream.黑暗之地_第6页", "(Because... in the candlelight... I couldn't see her shadow...)\n\nBy QYM");
        add("book.pasterdream.阴影小木屋_第1页", "After a long period of exploration and comparison, I've made a rough record of this dark world's environments.\n\nMost regions of this world are extremely dangerous.\n\nThe mountains covered by thick shadows — the flowing and condensing shadows constantly spawn horrific monsters that make one lose their wits at a mere glance;\n\n");
        add("book.pasterdream.阴影地下工作室_第1页", "Though this forest is relatively safe, to completely eliminate disturbance from Shadow Creatures, I decided to build a workspace underground.\nThanks to some supplies brought from the Overworld, I could at least build a small room for showering in the bedroom — after swimming through great tracts of shadow, one always wants a rinse.\nI planted most of the plants I could find across this world into flower beds. Though somewhat odd, tending these plants always relaxes me a little.\n");
        add("book.pasterdream.阴影地下工作室_第2页", "Among these gray-black plants, one I call \"Shadow Mushroom\" is especially special — unlike other plants, this mushroom seems to share properties with saplings: as long as it has enough growing space, it can grow into the fungus trees seen everywhere in the forest. It seems this forest's formation is closely tied to this mushroom.\nWhat's remarkable is that this mushroom must have ample space to grow.\nEarlier, when I planted it in a flower bed, it suddenly grew wild, wrecking the flower bed.\n");
        add("book.pasterdream.阴影地下工作室_第3页", "To prevent that from happening again, I moved it out of the bed and restricted its growing space. (The fully grown fungus tree next to it, though, I kept for continued research.)\nAfter tinkering with certain materials of this world, I finally reproduced the black long bed I used to come to this world. It seems lying on it can take me back to my original world.\nBut many unknowns in this world still await exploration; until I've unraveled them all, I don't plan to easily ret");
        add("book.pasterdream.阴影地下工作室_第4页", "turn to the Overworld.\nAh, it seems a beetle has crawled in. Though this beetle isn't aggressive, I still don't like being disturbed — time to go shoo it away.");
        add("book.pasterdream.阴影小木屋_第2页", "the plains piled with bones and ruined walls — endless Shadow Ghosts wail mournfully; one simply cannot stay long;\n\nonly here — this \"forest\" full of fungus \"trees\" — is quite safe.\n\nThe \"leaves\" of the fungi bear several glowing bodies; in this pitch-black world, such light seems able to dispel the shadows and suppress the spawning of Shadow Creatures.");
        add("book.pasterdream.阴影小木屋_第3页", "The natives here are a gentle kind of beetle; as long as you don't attack them, you'll be safe.\n\nWhile strolling through this forest, I happened upon a house.\n\nInterestingly, the walls of this cabin seem to be made from the stipes of the fungus trees.\n\n");
        add("book.pasterdream.阴影小木屋_第4页", "After peeling away the layer of shadow clinging to a stipe's surface, I found its appearance identical to the cabin's walls — a material similar to... stripped logs?\n\nThis house seems to have been abandoned for a long time; the only traces of human life are a few scattered carpets. Even the native beetles have made their home inside, and I had to drive them away to examine the interior carefully.");
        add("book.pasterdream.阴影小木屋_第5页", "While inspecting the floor, I found several patches of unnatural shadow attached to it.\n\nI stood at a distance and lightly pressed one patch with my foot.\n\nFrom beneath the shadow, a hand made of shadow shot out, grabbed my foot, and tried to pull me into the ground. I struggled desperately and finally pulled my foot free from the Shadow Hand.");
        add("book.pasterdream.阴影小木屋_第6页", "While trying to sweep away another patch of shadow, it changed shape before fading, becoming the hand-shaped monster I'd seen in the shadow-covered mountains. It took some effort to cut it to pieces.\n\nI have a feeling I'll encounter this kind of \"trap\" again elsewhere...\n\n\n\nBy: Jixing");
        add("book.pasterdream.>被阴影浸染的字迹潦草的笔记<_第1页", "Unbelievable — I actually escaped from the hands of that dreadful creature.\nThey were a pair of huge black hands with a white eye in each palm; just locking eyes with them made my whole body tremble; I couldn't muster the slightest will to fight.\nEven so, I forced up my courage to face them, only to find their terrible power far beyond my imagination.\nThe slightest attack against them provoked a fierce counterattack.\n");
        add("book.pasterdream.>被阴影浸染的字迹潦草的笔记<_第2页", "In the heat of battle I was so panicked that I couldn't even tell which hand I was attacking.\nHowever, I clearly remember: attacking one hand made it sprout a spike and flail it wildly;\nwhile attacking the other hand made it release a spire that seemed to hold immense energy.\nUpon seeing such dreadful counterattacks, I fled in panic at once — fleeing until I forgot how I even escaped.\n");
        add("book.pasterdream.>被阴影浸染的字迹潦草的笔记<_第3页", "To those who come later, I hope my disgraceful experience can contribute something to your exploration.\nUnless you possess power enough to tread this ghastly, dreadful world without any threat, please never approach the place of that \"eye\".");
        add("book.pasterdream.关于黑暗之手的随笔_第1页", "After roughly finishing my exploration of all this world's biomes, I gained a considerable understanding of nearly all its structures...\n...except for that \"eye\" wrapped in four \"fingers\".\nThe glowing portal at its center seems to lead to a simple but unsafe space.\nTo be safe, I managed to send a sturdy machine equipped with an image-transmission device into the portal to scout in my stead.\n");
        add("book.pasterdream.关于黑暗之手的随笔_第2页", "After passing through the portal, it slowly landed at the center of an \"arena\".\nThe image began to blur; the ground shook violently, and then two black giant hands emerged from thin air.\nUpon spotting this \"foreign object\" I'd thrown into the portal, the two hands immediately launched fierce attacks at it from front and back.\nIn the view, one hand suddenly charged over, flipping the machine over; then amid darkness and a gale, the machine's vision went dark and lost contact with me.\n");
        add("book.pasterdream.关于黑暗之手的随笔_第3页", "No good — too many variables this way; with only this much information, there's no chance of victory.\nEven so, I'll leave this note behind for now. Though it holds almost no valuable information, it should still be of some use to those who come later.\n");
        add("book.pasterdream.与黑色双手的决战和败北_第1页", "I write this note to warn those travelers who would challenge it: \"It\" is far more powerful than you can imagine.\nAs for what lies beyond that glowing portal, the notes left by the other Dreamseekers exploring the Lamp Shadow and by my friend gave me the answer: beyond the door is a small sealed world, home to a dreadful Shadow Creature shaped like a pair of hands.\nTo defeat it, I forged armor and weapons from the toughest metal obtainable in the pink dream, and after making every preparation I could think of,");
        add("book.pasterdream.与黑色双手的决战和败北_第2页", "I leapt into the portal.\nYet even with all my preparations, the battle was still exceedingly grueling.\nEndless shadow monsters surging from nowhere, and the black hands' ferocious assaults — they ceaselessly ravaged my mind, will, and stamina.\nEven so, I did my best to attack it, and in return received even fiercer counterattacks — but I still believed I had dealt it a heavy blow.\n");
        add("book.pasterdream.与黑色双手的决战和败北_第3页", "Just as I thought victory might be possible at this rate, something dreadful happened.\nIn an instant, my vision plunged into darkness. In the pitch black, it seemed endless Shadow Creatures writhed forth, and my attacks couldn't even pierce the thick layer of shadow around those hands.\nSurrounded by monsters, potions exhausted, badly wounded, I prayed desperately in my mind that this was only a dream, and grabbed the Pale Boneneedle to stab hard into my own arm.\n");
        add("book.pasterdream.与黑色双手的决战和败北_第4页", "After a sharp sting, my vision was seized by bright light. In the blink of an eye, I stood beside my familiar bed; but my body drenched in cold sweat, my armor riddled with cracks, and my empty potion bottles told me the ordeal just now was no simple dream.\nIndeed, to defeat this dreadful creature, one needs weapons that can suppress the shadow, or merge into it and destroy it from within.\nSo I must have missed something after all... Perhaps it would be better to wait for other aid to come\nand face it together as a bett");
        add("book.pasterdream.与黑色双手的决战和败北_第5页", "er choice.\nUntil then, I must find a way to obtain a more powerful weapon...");
        add("book.pasterdream.破风的骑士_第1页", "The crumbling ruins of Ancient Greek-style architecture form a circular temple, at whose center is enshrined an unremarkable altar.\n\nIs it for praying for rain? Or hoping to follow the wind's direction? Or enshrining one's patron god?\n\nI approached the half-brick altar at the center and crouched down, finding a black hole in the middle with a rolled-up strip of paper standing inside it.");
        add("book.pasterdream.破风的骑士_第2页", "On it were drawn some scrawled diagrams and a numbered sequence: a blue crystal, and 3 suits of armor seemingly made of metal.\n\nAnd at the very bottom of the paper was written:\n\n\"The Wind-Breaking Knight\" will drive away everything beyond what it protects...\n\n\nBy QYM");
        add("book.pasterdream.清晨的新风_第1页", "This is the beginning of a new day, and the arrival of a new wind direction.\n\nAccompanied by the sound of wind chimes, falling feathers, and the rising sun from the east.\n\nThe wind is this place's gift; following its direction will aid our exploration, while going against it may leave us unable to move an inch.\n\nThe wind not only guides the direction of our journey, but is also a special key.");
        add("book.pasterdream.清晨的新风_第2页", "The wind only blows when a new direction arrives; it cannot be predicted by any means.\n\nIf you miss the guidance of the morning wind, or cannot feel it physically outside this dream, a Wind Vane can cross the line between reality and dream to tell you the current wind direction.\n\nAnd some treasures scattered here can change the wind's influence on us.");
        add("book.pasterdream.清晨的新风_第3页", "There are still many secrets of the wind... perhaps one day, the wind will reveal them to us.\n\n\nBy QYM");

        add("message.pasterdream.twilight_lantern.activate_fail_no_knowledge", "You do not yet know how to activate the shadow lantern");
        add("message.pasterdream.twilight_lantern.activate_fail_no_crystal", "You need to light the shadow lantern with a Melt Dream Crystal Fragment");
        add("message.pasterdream.twilight_lantern.event_start", "§8The eerie lantern suddenly shakes violently, black shadows flow out from the wick.");
        add("message.pasterdream.twilight_lantern.event_mid", "§8The shadows materialize into physical form, hollow echoes resound from all around, followed by a shriek loud enough to tear eardrums.");
        add("message.pasterdream.twilight_lantern.event_voice", "§8You seem to hear a strange voice.");
        add("message.pasterdream.twilight_lantern.event_end", "§8Shadows no longer surge outward, the Twilight Lantern gradually returns to calm, a rift slowly appears in the sky above.");
        add("message.pasterdream.twilight_lantern.event_end_3", "§5\"Do not resist, surrender to your heart, together in eternal life\"");
        add("message.pasterdream.twilight_lantern.event_end_4", "§5\"Submit! Submit!! Submit!!!\"");
        add("message.pasterdream.twilight_lantern.event_end_5", "§5\"Come, come~ Come! ...Embrace us, sleep with us, merge with us, here is your only home\"");
        add("message.pasterdream.twilight_lantern.event_end_2", "§8The voices grow clearer, the repetitive words begin to irritate you.");
        add("message.pasterdream.twilight_lantern.event_ready", "§5You can now resonate with the Twilight Lantern, interact with the True Shadow Bed");
        add("message.pasterdream.twilight_lantern.data_reset", "Block data reset");
        add("message.pasterdream.twilight_lantern_location", "The end of the note records coordinates in the upper Nether: X: %s Z: %s");
        // ===== Wind Journey: wind direction mechanic =====
        add(ModItems.WIND_VANE.get(), "Wind Vane");
        add(ModItems.WIND_KNIGHT_FLAG.get(), "Wind Knight Flag");
        add(ModItems.FRACTURED_ANGEL_STATUE.get(), "Fractured Angel Statue");
        add(ModItems.PAPER_PLANE.get(), "Paper Plane");
